insert into licoes (nivel, ordem, titulo, sub, icon, explicacao, dica, exemplos, questoes) values
('B2', 6001, $$Unless, as long as, provided that$$, $$condições além do if$$, $$🔀$$, $$Condições sem if: unless (a menos que), as long as (contanto que), provided that (desde que), in case (caso/por precaução). Todos usam presente para falar do futuro.$$, $$Unless = if not: Unless you hurry = If you don't hurry.$$, $j$[{"en": "Unless you hurry, you'll miss the bus.", "pt": "A menos que se apresse, você perde o ônibus."}, {"en": "You can come as long as you behave.", "pt": "Você pode vir contanto que se comporte."}, {"en": "Take an umbrella in case it rains.", "pt": "Leve um guarda-chuva caso chova."}]$j$::jsonb, $j$[{"q": "'Unless' =", "ctx": "", "opts": ["a menos que", "sempre que", "porque", "apesar de"], "ans": 0, "exp": "= if not."}, {"q": "'As long as' =", "ctx": "", "opts": ["contanto que", "tão longo quanto", "enquanto isso", "até que"], "ans": 0, "exp": "Condição."}, {"q": "'In case it rains' =", "ctx": "", "opts": ["por precaução, caso chova", "dentro da chuva", "se choveu ontem", "porque chove"], "ans": 0, "exp": "Precaução."}, {"q": "Complete: 'Unless you study, you ___ pass.'", "ctx": "", "opts": ["won't", "will", "would", "did"], "ans": 0, "exp": "Sem estudar, não passa."}, {"q": "'Provided that' é:", "ctx": "", "opts": ["formal para 'desde que'", "fornecido", "provado", "provisório"], "ans": 0, "exp": "Condição formal."}, {"q": "Depois de unless usamos:", "ctx": "", "opts": ["presente (sem will)", "will sempre", "would", "passado perfeito"], "ans": 0, "exp": "Unless you HURRY."}]$j$::jsonb),
('B2', 6002, $$Future in the past$$, $$was going to$$, $$⏪$$, $$Falar de um futuro visto do passado: was/were going to (ia fazer), would (faria), was about to (estava prestes a). Perfeito para planos que mudaram.$$, $$"I was going to call you" = a intenção existia... mas algo aconteceu.$$, $j$[{"en": "I was going to call you, but I forgot.", "pt": "Eu ia te ligar, mas esqueci."}, {"en": "She said she would help us.", "pt": "Ela disse que ajudaria a gente."}, {"en": "We were about to leave when he arrived.", "pt": "Estávamos prestes a sair quando ele chegou."}]$j$::jsonb, $j$[{"q": "'Eu ia viajar' =", "ctx": "", "opts": ["I was going to travel", "I will travel", "I am going to travel", "I travel"], "ans": 0, "exp": "Plano no passado."}, {"q": "'Estava prestes a sair' =", "ctx": "", "opts": ["was about to leave", "was going leave", "am about to leave", "left about"], "ans": 0, "exp": "About to = iminente."}, {"q": "'Ela disse que viria' =", "ctx": "", "opts": ["she said she would come", "she said she will come", "she says she comes", "she said coming"], "ans": 0, "exp": "Would = futuro do passado."}, {"q": "'I was going to...' sugere que:", "ctx": "", "opts": ["o plano mudou", "eu fui mesmo", "vou amanhã", "é um sonho"], "ans": 0, "exp": "Intenção não realizada."}, {"q": "Futuro do passado de 'will':", "ctx": "", "opts": ["would", "was will", "willed", "going to"], "ans": 0, "exp": "Will → would."}, {"q": "'We were to meet at 5' (formal) =", "ctx": "", "opts": ["devíamos nos encontrar às 5", "nos encontramos às 5", "talvez às 5", "não fomos"], "ans": 0, "exp": "Plano/combinado formal."}]$j$::jsonb),
('B2', 6003, $$Will, going to ou present continuous?$$, $$3 futuros, 3 usos$$, $$🔮$$, $$Cada futuro tem seu papel: WILL para decisões na hora e previsões de opinião; GOING TO para planos e evidências; PRESENT CONTINUOUS para compromissos já agendados.$$, $$"I'm seeing the dentist at 3" = já está na agenda. Going to = intenção; will = decidi agora.$$, $j$[{"en": "I'll get the door!", "pt": "Eu atendo a porta! (decidi agora)"}, {"en": "We're going to renovate the house.", "pt": "Vamos reformar a casa (plano)."}, {"en": "I'm flying to Recife on Monday.", "pt": "Vou voar para Recife na segunda (agendado)."}]$j$::jsonb, $j$[{"q": "Decisão tomada AGORA:", "ctx": "", "opts": ["will", "going to", "present continuous", "past simple"], "ans": 0, "exp": "I'll help you!"}, {"q": "Plano já decidido antes:", "ctx": "", "opts": ["going to", "will", "would", "present perfect"], "ans": 0, "exp": "Intenção prévia."}, {"q": "Compromisso na agenda:", "ctx": "", "opts": ["present continuous", "will", "would", "past continuous"], "ans": 0, "exp": "I'm meeting him at 5."}, {"q": "Céu preto: 'It ___ rain.'", "ctx": "", "opts": ["is going to", "will maybe", "is raining yesterday", "would"], "ans": 0, "exp": "Evidência = going to."}, {"q": "'I think she ___ win' (opinião):", "ctx": "", "opts": ["will", "is winning", "is going to won", "won"], "ans": 0, "exp": "Previsão de opinião = will."}, {"q": "O trem tem horário fixo: 'The train ___ at 8.'", "ctx": "", "opts": ["leaves", "will leaving", "is going to leaves", "left"], "ans": 0, "exp": "Horário fixo = present simple."}]$j$::jsonb),
('B2', 6004, $$Time clauses no futuro$$, $$when + presente$$, $$⏳$$, $$Depois de when, as soon as, until, before, after e while falando do futuro, usa-se PRESENTE (nunca will): When I arrive, I'll call you.$$, $$when I will arrive ❌ → when I arrive ✅. O will fica na oração principal.$$, $j$[{"en": "When I arrive, I'll call you.", "pt": "Quando eu chegar, te ligo."}, {"en": "As soon as she finishes, we can go.", "pt": "Assim que ela terminar, podemos ir."}, {"en": "I'll wait here until you get back.", "pt": "Vou esperar aqui até você voltar."}]$j$::jsonb, $j$[{"q": "Correto:", "ctx": "", "opts": ["When I arrive, I'll call", "When I'll arrive, I call", "When I arrived, I'll call", "When I arriving, call"], "ans": 0, "exp": "When + presente."}, {"q": "'Assim que' =", "ctx": "", "opts": ["as soon as", "as fast as", "so soon that", "when soon"], "ans": 0, "exp": "As soon as."}, {"q": "'I'll stay ___ you return':", "ctx": "", "opts": ["until", "during", "while will", "by"], "ans": 0, "exp": "Until + presente."}, {"q": "Depois de 'when' (futuro) usamos:", "ctx": "", "opts": ["presente simples", "will", "would", "going to"], "ans": 0, "exp": "Regra de ouro."}, {"q": "'Before you ___, turn off the lights.'", "ctx": "", "opts": ["leave", "will leave", "left", "leaving to"], "ans": 0, "exp": "Presente."}, {"q": "'After she ___ dinner, we'll watch TV.'", "ctx": "", "opts": ["has", "will have", "had had", "having"], "ans": 0, "exp": "Presente (ou pres. perfect)."}]$j$::jsonb),
('B2', 6005, $$Tempos narrativos$$, $$contando histórias$$, $$📖$$, $$Toda boa história mistura três tempos: past continuous (cenário: was raining), past simple (ação: arrived) e past perfect (antes disso: had left). É o kit do contador de histórias.$$, $$Cenário → continuous; ação → simple; flashback → perfect.$$, $j$[{"en": "It was raining when I got home.", "pt": "Estava chovendo quando cheguei em casa."}, {"en": "When I got there, everyone had left.", "pt": "Quando cheguei lá, todos já tinham ido."}, {"en": "While she was cooking, the phone rang.", "pt": "Enquanto ela cozinhava, o telefone tocou."}]$j$::jsonb, $j$[{"q": "Cenário/ação em andamento:", "ctx": "", "opts": ["past continuous", "past simple", "past perfect", "present perfect"], "ans": 0, "exp": "Was raining..."}, {"q": "Ação principal da história:", "ctx": "", "opts": ["past simple", "past continuous", "future", "imperative"], "ans": 0, "exp": "Arrived, said, went."}, {"q": "O que aconteceu ANTES da história:", "ctx": "", "opts": ["past perfect", "past simple", "present perfect", "will"], "ans": 0, "exp": "Had left."}, {"q": "'While I ___ TV, she called.'", "ctx": "", "opts": ["was watching", "watched once", "had watch", "watch"], "ans": 0, "exp": "Ação em andamento."}, {"q": "'Everyone ___ when I arrived' (já tinham saído):", "ctx": "", "opts": ["had left", "left", "was leaving", "leave"], "ans": 0, "exp": "Antes de eu chegar."}, {"q": "Sequência típica de narrativa:", "ctx": "", "opts": ["continuous + simple + perfect", "só present", "só future", "imperativo"], "ans": 0, "exp": "O trio narrativo."}]$j$::jsonb),
('B2', 6006, $$State verbs$$, $$know não vai para -ing$$, $$🧠$$, $$Verbos de estado não usam -ing: know, believe, love, hate, own, need, seem, belong. Descrevem estados, não ações: I know ✅, I am knowing ❌.$$, $$McDonald's quebrou a regra de propósito no "I'm lovin' it" — marketing, não gramática!$$, $j$[{"en": "I know the answer.", "pt": "Eu sei a resposta."}, {"en": "This bag belongs to Sarah.", "pt": "Esta bolsa pertence à Sarah."}, {"en": "You seem tired today.", "pt": "Você parece cansado hoje."}]$j$::jsonb, $j$[{"q": "Correto:", "ctx": "", "opts": ["I know him", "I am knowing him", "I knowing him", "I am know him"], "ans": 0, "exp": "Know = estado."}, {"q": "Verbo de ESTADO:", "ctx": "", "opts": ["believe", "run", "cook", "jump"], "ans": 0, "exp": "Crença = estado."}, {"q": "'Ela precisa de ajuda AGORA':", "ctx": "", "opts": ["She needs help", "She is needing help", "She needing help", "She need helping"], "ans": 0, "exp": "Need não vai para -ing."}, {"q": "'Have' vai para -ing quando significa:", "ctx": "", "opts": ["atividade (having lunch)", "posse (having a car)", "obrigação", "nunca"], "ans": 0, "exp": "Having lunch ✅; having a car ❌."}, {"q": "'Think' com -ing =", "ctx": "", "opts": ["considerando (I'm thinking about it)", "opinião fixa", "erro sempre", "futuro"], "ans": 0, "exp": "Opinião = think; ponderar = thinking."}, {"q": "Qual NÃO é state verb:", "ctx": "", "opts": ["cook", "own", "seem", "belong"], "ans": 0, "exp": "Cozinhar é ação."}]$j$::jsonb),
('B2', 6007, $$Stop, remember, try + -ing ou to?$$, $$sentidos que mudam$$, $$🔁$$, $$Alguns verbos mudam de sentido: stop smoking (parar de fumar) × stop to smoke (parar para fumar); remember doing (lembrar de ter feito) × remember to do (lembrar de fazer); try doing (experimentar) × try to do (esforçar-se).$$, $$"I stopped to smoke" = você parou o carro PARA fumar. Cuidado!$$, $j$[{"en": "He stopped smoking last year.", "pt": "Ele parou de fumar ano passado."}, {"en": "Remember to lock the door!", "pt": "Lembre-se de trancar a porta!"}, {"en": "I remember locking the door.", "pt": "Eu lembro de ter trancado a porta."}]$j$::jsonb, $j$[{"q": "'Parar de fumar':", "ctx": "", "opts": ["stop smoking", "stop to smoke", "stop smoke", "stop for smoking"], "ans": 0, "exp": "Stop + -ing = cessar."}, {"q": "'Lembrar de fazer (futuro)':", "ctx": "", "opts": ["remember to do", "remember doing", "remind doing", "memory to do"], "ans": 0, "exp": "To = tarefa."}, {"q": "'Lembro de ter feito (passado)':", "ctx": "", "opts": ["remember doing", "remember to do", "remind to do", "remembered do"], "ans": 0, "exp": "-ing = memória."}, {"q": "'Try opening the window' =", "ctx": "", "opts": ["experimente abrir", "esforce-se para abrir", "não abra", "finja abrir"], "ans": 0, "exp": "-ing = tentativa/experimento."}, {"q": "'She stopped to rest' =", "ctx": "", "opts": ["parou para descansar", "parou de descansar", "nunca descansou", "descansa sempre"], "ans": 0, "exp": "To = finalidade."}, {"q": "'Forget doing' vs 'forget to do':", "ctx": "", "opts": ["fiz e esqueci × esqueci de fazer", "iguais", "ambos futuro", "ambos passado"], "ans": 0, "exp": "Mesma lógica do remember."}]$j$::jsonb),
('B2', 6008, $$Question tags$$, $$né? no inglês$$, $$❓$$, $$A confirmação no fim da frase: You're Brazilian, aren't you? Frase positiva → tag negativa; frase negativa → tag positiva. O verbo auxiliar comanda.$$, $$I am → aren't I? (exceção famosa!). Let's → shall we?$$, $j$[{"en": "You're coming, aren't you?", "pt": "Você vem, né?"}, {"en": "She doesn't like fish, does she?", "pt": "Ela não gosta de peixe, gosta?"}, {"en": "Let's start, shall we?", "pt": "Vamos começar, que tal?"}]$j$::jsonb, $j$[{"q": "'You're tired, ___?'", "ctx": "", "opts": ["aren't you", "are you", "isn't it", "don't you"], "ans": 0, "exp": "Positiva → negativa."}, {"q": "'He can't swim, ___?'", "ctx": "", "opts": ["can he", "can't he", "does he", "is he"], "ans": 0, "exp": "Negativa → positiva."}, {"q": "'I'm late, ___?' (exceção):", "ctx": "", "opts": ["aren't I", "amn't I", "am I", "isn't I"], "ans": 0, "exp": "Aren't I é a forma aceita."}, {"q": "'Let's go, ___?'", "ctx": "", "opts": ["shall we", "will we", "do we", "let we"], "ans": 0, "exp": "Let's → shall we."}, {"q": "'She went home, ___?'", "ctx": "", "opts": ["didn't she", "doesn't she", "hasn't she", "wasn't she"], "ans": 0, "exp": "Past simple → didn't."}, {"q": "'They've finished, ___?'", "ctx": "", "opts": ["haven't they", "didn't they", "aren't they", "don't they"], "ans": 0, "exp": "Have → haven't."}]$j$::jsonb),
('B2', 6009, $$So do I / Neither do I$$, $$eu também (ou também não)$$, $$🤝$$, $$Concordar como nativo: 'I love coffee.' — 'So do I' (eu também). 'I don't smoke.' — 'Neither do I' (nem eu). O auxiliar copia o da frase original.$$, $$Me too/me neither = informal. So do I / Neither do I = elegante.$$, $j$[{"en": "\"I love this song.\" \"So do I!\"", "pt": "\"Amo essa música.\" \"Eu também!\""}, {"en": "\"I can't swim.\" \"Neither can I.\"", "pt": "\"Não sei nadar.\" \"Nem eu.\""}, {"en": "\"I went to the show.\" \"So did I.\"", "pt": "\"Fui ao show.\" \"Eu também.\""}]$j$::jsonb, $j$[{"q": "'I love pizza.' → eu também:", "ctx": "", "opts": ["So do I", "So I do", "Neither do I", "So am I"], "ans": 0, "exp": "So + auxiliar + I."}, {"q": "'I can't drive.' → nem eu:", "ctx": "", "opts": ["Neither can I", "So can I", "Neither do I", "Either can I"], "ans": 0, "exp": "Copia o can."}, {"q": "'I'm tired.' → eu também:", "ctx": "", "opts": ["So am I", "So do I", "So I am", "Neither am I"], "ans": 0, "exp": "Verbo be → am."}, {"q": "'I saw the film.' → eu também:", "ctx": "", "opts": ["So did I", "So saw I", "So do I", "So have I"], "ans": 0, "exp": "Past simple → did."}, {"q": "'I've been there.' → eu também:", "ctx": "", "opts": ["So have I", "So did I", "So am I", "So I have"], "ans": 0, "exp": "Copia o have."}, {"q": "'Neither' usa-se com frase:", "ctx": "", "opts": ["negativa", "positiva", "interrogativa", "imperativa"], "ans": 0, "exp": "Nem eu = negativa."}]$j$::jsonb),
('B2', 6010, $$Reflexivos e each other$$, $$myself × each other$$, $$🪞$$, $$Myself, yourself, themselves = a ação volta para a própria pessoa. Each other = ação mútua: They looked at themselves (no espelho) × They looked at each other (um para o outro).$$, $$By myself = sozinho. Enjoy yourself! = divirta-se!$$, $j$[{"en": "I taught myself English.", "pt": "Aprendi inglês sozinho."}, {"en": "They love each other.", "pt": "Eles se amam (um ao outro)."}, {"en": "She lives by herself.", "pt": "Ela mora sozinha."}]$j$::jsonb, $j$[{"q": "'Eles se olharam (mutuamente)':", "ctx": "", "opts": ["at each other", "at themselves", "at theirselves", "each other at"], "ans": 0, "exp": "Mútuo = each other."}, {"q": "'Me cortei':", "ctx": "", "opts": ["I cut myself", "I cut me", "I cut mine", "I cut himself"], "ans": 0, "exp": "Reflexivo."}, {"q": "'By myself' =", "ctx": "", "opts": ["sozinho", "para mim", "comigo mesmo bravo", "à minha maneira"], "ans": 0, "exp": "Sem companhia."}, {"q": "'Divirta-se!':", "ctx": "", "opts": ["Enjoy yourself!", "Enjoy you!", "Fun yourself!", "Enjoy myself!"], "ans": 0, "exp": "Enjoy yourself."}, {"q": "Reflexivo de they:", "ctx": "", "opts": ["themselves", "theirselves", "themself only", "theyselves"], "ans": 0, "exp": "Themselves."}, {"q": "'Help ___ to some coffee' (sirva-se):", "ctx": "", "opts": ["yourself", "you", "each other", "myself"], "ans": 0, "exp": "Help yourself."}]$j$::jsonb),
('B2', 6011, $$Too e Enough$$, $$demais × suficiente$$, $$⚖️$$, $$TOO vem antes do adjetivo (too hot = quente demais); ENOUGH vem depois (hot enough = quente o bastante) mas antes do substantivo (enough money). Com infinitivo: too tired to work.$$, $$too much + incontável, too many + contável: too much noise, too many people.$$, $j$[{"en": "The coffee is too hot to drink.", "pt": "O café está quente demais para beber."}, {"en": "Is the water warm enough?", "pt": "A água está morna o suficiente?"}, {"en": "We don't have enough time.", "pt": "Não temos tempo suficiente."}]$j$::jsonb, $j$[{"q": "'Caro demais':", "ctx": "", "opts": ["too expensive", "expensive too", "enough expensive", "much expensive"], "ans": 0, "exp": "Too + adjetivo."}, {"q": "'Alto o bastante':", "ctx": "", "opts": ["tall enough", "enough tall", "too tall", "tall too much"], "ans": 0, "exp": "Adjetivo + enough."}, {"q": "'Dinheiro suficiente':", "ctx": "", "opts": ["enough money", "money enough", "too money", "much enough money"], "ans": 0, "exp": "Enough + substantivo."}, {"q": "'Gente demais':", "ctx": "", "opts": ["too many people", "too much people", "people too", "enough people over"], "ans": 0, "exp": "Contável = many."}, {"q": "'Barulho demais':", "ctx": "", "opts": ["too much noise", "too many noise", "noise too many", "very noise"], "ans": 0, "exp": "Incontável = much."}, {"q": "'Cansado demais para dirigir':", "ctx": "", "opts": ["too tired to drive", "too tired for drive", "tired too to drive", "enough tired to drive"], "ans": 0, "exp": "Too + adj + to."}]$j$::jsonb),
('B2', 6012, $$Finalidade: so that, in order to$$, $$para quê?$$, $$🎯$$, $$Expressar propósito: to/in order to + verbo (para fazer), so that + frase (para que), so as not to (para não), for + substantivo (for lunch).$$, $$Para NÃO fazer: in order not to / so as not to — nunca 'for not doing'.$$, $j$[{"en": "I came here to learn English.", "pt": "Vim aqui para aprender inglês."}, {"en": "Speak up so that everyone can hear you.", "pt": "Fale alto para que todos ouçam."}, {"en": "He left early so as not to miss the train.", "pt": "Saiu cedo para não perder o trem."}]$j$::jsonb, $j$[{"q": "'Para aprender' (simples):", "ctx": "", "opts": ["to learn", "for learn", "for to learn", "so learn"], "ans": 0, "exp": "To + verbo."}, {"q": "'Para que todos vejam':", "ctx": "", "opts": ["so that everyone can see", "for everyone see", "to everyone see", "so everyone seeing"], "ans": 0, "exp": "So that + frase."}, {"q": "'Para não esquecer':", "ctx": "", "opts": ["so as not to forget", "for not forget", "to not forgetting", "so that no forget"], "ans": 0, "exp": "So as not to."}, {"q": "'In order to' é:", "ctx": "", "opts": ["formal para 'para'", "em ordem", "uma ordem", "organizado"], "ans": 0, "exp": "= to, mais formal."}, {"q": "'Vim para o almoço':", "ctx": "", "opts": ["I came for lunch", "I came to lunch verb", "I came so lunch", "I came in order lunch"], "ans": 0, "exp": "For + substantivo."}, {"q": "'Anotei para não esquecer':", "ctx": "", "opts": ["I wrote it down so that I wouldn't forget", "for I not forget", "to I don't forget", "so as I forget not"], "ans": 0, "exp": "So that + wouldn't."}]$j$::jsonb),
('B2', 6013, $$Adjetivo + preposição$$, $$good at, afraid of$$, $$🧩$$, $$Pares fixos: good/bad at (bom/ruim em), afraid of (com medo de), interested in (interessado em), proud of (orgulhoso de), responsible for (responsável por), similar to (parecido com).$$, $$Depois da preposição, verbo vai de -ing: good at cooking.$$, $j$[{"en": "She's really good at math.", "pt": "Ela é muito boa em matemática."}, {"en": "I'm interested in photography.", "pt": "Tenho interesse em fotografia."}, {"en": "He's afraid of spiders.", "pt": "Ele tem medo de aranha."}]$j$::jsonb, $j$[{"q": "'Bom em inglês':", "ctx": "", "opts": ["good at English", "good in English", "good on English", "good with English only"], "ans": 0, "exp": "Good AT."}, {"q": "'Com medo de altura':", "ctx": "", "opts": ["afraid of heights", "afraid from heights", "afraid with heights", "afraid at heights"], "ans": 0, "exp": "Afraid OF."}, {"q": "'Interessado em arte':", "ctx": "", "opts": ["interested in art", "interested on art", "interested at art", "interested for art"], "ans": 0, "exp": "Interested IN."}, {"q": "'Orgulhoso de você':", "ctx": "", "opts": ["proud of you", "proud with you", "proud for you", "proud at you"], "ans": 0, "exp": "Proud OF."}, {"q": "'Responsável pelo projeto':", "ctx": "", "opts": ["responsible for the project", "responsible of the project", "responsible by the project", "responsible at it"], "ans": 0, "exp": "Responsible FOR."}, {"q": "'Parecido com o pai':", "ctx": "", "opts": ["similar to his father", "similar with his father", "similar of his father", "similar as his father"], "ans": 0, "exp": "Similar TO."}]$j$::jsonb),
('B2', 6014, $$Substantivo + preposição$$, $$the reason for$$, $$🔗$$, $$Substantivos também têm par fixo: reason for (razão para), solution to (solução para), increase in (aumento de), advantage of (vantagem de), relationship with (relação com), demand for (demanda por).$$, $$Solution TO (não for!): the solution to the problem.$$, $j$[{"en": "What's the reason for the delay?", "pt": "Qual a razão do atraso?"}, {"en": "There's been an increase in prices.", "pt": "Houve um aumento nos preços."}, {"en": "We found a solution to the problem.", "pt": "Achamos uma solução para o problema."}]$j$::jsonb, $j$[{"q": "'A razão do atraso':", "ctx": "", "opts": ["the reason for the delay", "the reason of the delay", "the reason to delay", "the reason at the delay"], "ans": 0, "exp": "Reason FOR."}, {"q": "'Solução para o problema':", "ctx": "", "opts": ["solution to the problem", "solution for the problem", "solution of the problem", "solution at the problem"], "ans": 0, "exp": "Solution TO."}, {"q": "'Aumento nos preços':", "ctx": "", "opts": ["increase in prices", "increase of prices only", "increase on prices", "increase to prices"], "ans": 0, "exp": "Increase IN."}, {"q": "'Vantagem de morar aqui':", "ctx": "", "opts": ["advantage of living here", "advantage to live here", "advantage for living here", "advantage in live here"], "ans": 0, "exp": "Advantage OF + -ing."}, {"q": "'Relação com o cliente':", "ctx": "", "opts": ["relationship with the client", "relationship of the client", "relationship to client always", "relationship at the client"], "ans": 0, "exp": "With."}, {"q": "'Demanda por comida orgânica':", "ctx": "", "opts": ["demand for organic food", "demand of organic food", "demand to organic food", "demand in organic food"], "ans": 0, "exp": "Demand FOR."}]$j$::jsonb),
('B2', 6015, $$Ordem dos adjetivos$$, $$big old red car$$, $$🚗$$, $$Vários adjetivos? Ordem fixa: opinião → tamanho → idade → formato → cor → origem → material → uso. A beautiful big old round brown Italian leather bag (ufa!).$$, $$Na prática, use no máximo 2-3: a lovely old house.$$, $j$[{"en": "She bought a beautiful red dress.", "pt": "Ela comprou um lindo vestido vermelho."}, {"en": "It's a small wooden table.", "pt": "É uma mesinha de madeira."}, {"en": "He drives a big old German car.", "pt": "Ele dirige um carro alemão grande e velho."}]$j$::jsonb, $j$[{"q": "Ordem correta:", "ctx": "", "opts": ["a nice small black cat", "a black small nice cat", "a small nice black cat", "a black nice small cat"], "ans": 0, "exp": "Opinião-tamanho-cor."}, {"q": "Opinião vem:", "ctx": "", "opts": ["antes de tudo", "por último", "depois da cor", "depois do tamanho"], "ans": 0, "exp": "Lovely little house."}, {"q": "Correto:", "ctx": "", "opts": ["an old Italian restaurant", "an Italian old restaurant", "a restaurant old Italian", "an old restaurant Italian"], "ans": 0, "exp": "Idade antes de origem."}, {"q": "Cor vem antes de:", "ctx": "", "opts": ["material", "tamanho", "opinião", "idade"], "ans": 0, "exp": "Red leather jacket."}, {"q": "Correto:", "ctx": "", "opts": ["a big round wooden table", "a wooden big round table", "a round big wooden table", "a wooden round big table"], "ans": 0, "exp": "Tamanho-formato-material."}, {"q": "'Uma caneca de café grande e branca':", "ctx": "", "opts": ["a big white coffee mug", "a white big coffee mug", "a coffee big white mug", "a big coffee white mug"], "ans": 0, "exp": "Tamanho-cor-uso."}]$j$::jsonb),
('B2', 6016, $$Adjetivos compostos$$, $$well-known$$, $$🧱$$, $$Adjetivos de duas peças com hífen: well-known (famoso), five-star (cinco estrelas), part-time (meio período), old-fashioned (antiquado), last-minute (de última hora). Antes do substantivo, sempre no singular: a five-star hotel (não fives-stars!).$$, $$She's 25 years old MAS a 25-year-old woman (sem s!).$$, $j$[{"en": "It's a well-known brand in Brazil.", "pt": "É uma marca famosa no Brasil."}, {"en": "They stayed at a five-star hotel.", "pt": "Ficaram num hotel cinco estrelas."}, {"en": "She has a part-time job.", "pt": "Ela tem um emprego de meio período."}]$j$::jsonb, $j$[{"q": "'Um menino de 10 anos':", "ctx": "", "opts": ["a ten-year-old boy", "a ten-years-old boy", "a ten years boy", "a boy of ten-years-old"], "ans": 0, "exp": "Sem s no composto."}, {"q": "'Famoso/conhecido':", "ctx": "", "opts": ["well-known", "good-known", "much-known", "very-known"], "ans": 0, "exp": "Well-known."}, {"q": "'De última hora':", "ctx": "", "opts": ["last-minute", "late-minute", "end-minute", "final-hour"], "ans": 0, "exp": "A last-minute decision."}, {"q": "'Antiquado':", "ctx": "", "opts": ["old-fashioned", "old-fashion", "ancient-style", "past-fashioned"], "ans": 0, "exp": "Old-fashioned."}, {"q": "'Meio período':", "ctx": "", "opts": ["part-time", "half-time job", "middle-time", "some-time"], "ans": 0, "exp": "Part-time."}, {"q": "'Viagem de três horas':", "ctx": "", "opts": ["a three-hour trip", "a three-hours trip", "a trip of three-hours", "a three hour's trip"], "ans": 0, "exp": "Singular no composto."}]$j$::jsonb),
('B2', 6017, $$Hard × Hardly, Late × Lately$$, $$advérbios traiçoeiros$$, $$🪤$$, $$Pegadinha clássica: hard (duro/muito) × hardly (quase não); late (tarde) × lately (ultimamente); near (perto) × nearly (quase); high (alto) × highly (altamente/muito).$$, $$"I hardly work" = quase não trabalho. Cuidado com o que você diz ao chefe!$$, $j$[{"en": "She works very hard.", "pt": "Ela trabalha muito."}, {"en": "I hardly know him.", "pt": "Eu mal o conheço."}, {"en": "Have you seen any good films lately?", "pt": "Você viu algum filme bom ultimamente?"}]$j$::jsonb, $j$[{"q": "'Trabalhar duro':", "ctx": "", "opts": ["work hard", "work hardly", "hardly work", "work hardful"], "ans": 0, "exp": "Hard = advérbio também."}, {"q": "'Hardly' =", "ctx": "", "opts": ["quase não", "duramente", "com força", "rapidamente"], "ans": 0, "exp": "Hardly any = quase nenhum."}, {"q": "'Ultimamente':", "ctx": "", "opts": ["lately", "late", "later", "lastly"], "ans": 0, "exp": "Lately."}, {"q": "'Cheguei tarde':", "ctx": "", "opts": ["I arrived late", "I arrived lately", "I lately arrived", "I arrived latest"], "ans": 0, "exp": "Late = tarde."}, {"q": "'Nearly' =", "ctx": "", "opts": ["quase", "perto (lugar)", "carinhosamente", "nunca"], "ans": 0, "exp": "Nearly finished = quase pronto."}, {"q": "'Highly recommended' =", "ctx": "", "opts": ["muito recomendado", "recomendado lá no alto", "pouco recomendado", "raramente indicado"], "ans": 0, "exp": "Highly = intensificador."}]$j$::jsonb),
('B2', 6018, $$Quantificadores avançados$$, $$plenty of, hardly any$$, $$🧺$$, $$Além do much/many: plenty of (de sobra), a great deal of (uma grande quantidade — incontável), several (vários), hardly any (quase nenhum), loads of (um monte — informal).$$, $$Plenty of = suficiente E sobrando. "Don't worry, we have plenty of time."$$, $j$[{"en": "We have plenty of time.", "pt": "Temos tempo de sobra."}, {"en": "There's hardly any milk left.", "pt": "Quase não sobrou leite."}, {"en": "She has several job offers.", "pt": "Ela tem várias propostas de emprego."}]$j$::jsonb, $j$[{"q": "'De sobra':", "ctx": "", "opts": ["plenty of", "a few of", "hardly any", "none of"], "ans": 0, "exp": "Plenty!"}, {"q": "'Quase nenhum dinheiro':", "ctx": "", "opts": ["hardly any money", "hardly no money", "almost none money", "few money"], "ans": 0, "exp": "Hardly any."}, {"q": "'A great deal of' usa-se com:", "ctx": "", "opts": ["incontáveis", "contáveis", "pessoas só", "números"], "ans": 0, "exp": "A great deal of time."}, {"q": "'Vários' (contável):", "ctx": "", "opts": ["several", "much", "a great deal", "a little"], "ans": 0, "exp": "Several books."}, {"q": "'Um monte de' (informal):", "ctx": "", "opts": ["loads of", "deal of", "plenty deal", "several of"], "ans": 0, "exp": "Loads of fun."}, {"q": "'The vast majority of' =", "ctx": "", "opts": ["a grande maioria de", "o vasto oceano de", "a metade de", "alguns"], "ans": 0, "exp": "Formal."}]$j$::jsonb),
('B2', 6019, $$Each × Every$$, $$cada × todo$$, $$👣$$, $$Each = cada um individualmente (foco no indivíduo); every = todos como grupo (foco no conjunto). Each of them ✅, every of them ❌. Every day = frequência.$$, $$Each pode ir sozinho no fim: They cost $5 each. Every não.$$, $j$[{"en": "Each student received a certificate.", "pt": "Cada aluno recebeu um certificado."}, {"en": "Every seat was taken.", "pt": "Todos os lugares estavam ocupados."}, {"en": "The tickets cost $10 each.", "pt": "Os ingressos custam 10 dólares cada."}]$j$::jsonb, $j$[{"q": "'___ of the students passed':", "ctx": "", "opts": ["Each", "Every", "All every", "Everyone"], "ans": 0, "exp": "Each of + pronome/the."}, {"q": "Foco no grupo todo:", "ctx": "", "opts": ["every", "each", "either", "both"], "ans": 0, "exp": "Every guest = todos."}, {"q": "'Custam R$5 cada':", "ctx": "", "opts": ["They cost R$5 each", "They cost R$5 every", "Each they cost R$5", "They each every cost"], "ans": 0, "exp": "Each no fim."}, {"q": "'Todo dia':", "ctx": "", "opts": ["every day", "each days", "all day only", "every days"], "ans": 0, "exp": "Every day."}, {"q": "Each e every usam verbo no:", "ctx": "", "opts": ["singular", "plural", "passado", "gerúndio"], "ans": 0, "exp": "Each/every person IS."}, {"q": "'A cada dois dias':", "ctx": "", "opts": ["every two days", "each two days", "all two days", "two every days"], "ans": 0, "exp": "Every + número."}]$j$::jsonb),
('B2', 6020, $$Another × Other × Others$$, $$outro, outros$$, $$🔄$$, $$Another + singular (mais um: another coffee); other + plural/incontável (outros: other people); others sozinho (os outros: the others); the other = o outro (de dois).$$, $$another = an + other, sempre singular. "Another one, please!"$$, $j$[{"en": "Would you like another cup of coffee?", "pt": "Quer outra xícara de café?"}, {"en": "Some people agree; others don't.", "pt": "Algumas pessoas concordam; outras não."}, {"en": "Where's the other sock?", "pt": "Cadê a outra meia (do par)?"}]$j$::jsonb, $j$[{"q": "'Mais um café':", "ctx": "", "opts": ["another coffee", "other coffee", "others coffee", "an other one coffee"], "ans": 0, "exp": "Another + singular."}, {"q": "'Outras pessoas':", "ctx": "", "opts": ["other people", "another people", "others people", "the anothers"], "ans": 0, "exp": "Other + plural."}, {"q": "'Uns concordam, OUTROS não':", "ctx": "", "opts": ["others", "other", "another", "each other"], "ans": 0, "exp": "Others sozinho."}, {"q": "'O outro (de dois)':", "ctx": "", "opts": ["the other", "another", "the others one", "other the"], "ans": 0, "exp": "The other sock."}, {"q": "'Outros 20 minutos':", "ctx": "", "opts": ["another 20 minutes", "other 20 minutes", "others 20 minutes", "more another minutes"], "ans": 0, "exp": "Another + número (bloco)."}, {"q": "'Each other' =", "ctx": "", "opts": ["um ao outro (mútuo)", "cada outro", "outro qualquer", "juntos"], "ans": 0, "exp": "They help each other."}]$j$::jsonb),
('B2', 6021, $$Little, a little, few, a few$$, $$quase nada × um pouco$$, $$🌗$$, $$COM 'a' = positivo (tem um pouco): a little water, a few friends. SEM 'a' = negativo (quase nada): little hope (pouca esperança), few options (poucas opções). Little/a little = incontável; few/a few = contável.$$, $$I have a few friends 🙂 × I have few friends 🙁 — o 'a' muda o humor da frase!$$, $j$[{"en": "We have a little time before the show.", "pt": "Temos um tempinho antes do show."}, {"en": "There's little hope of finding them.", "pt": "Há pouca esperança de encontrá-los."}, {"en": "She invited a few close friends.", "pt": "Ela convidou alguns amigos próximos."}]$j$::jsonb, $j$[{"q": "'Um pouco de água' (positivo):", "ctx": "", "opts": ["a little water", "little water", "a few water", "few water"], "ans": 0, "exp": "A little + incontável."}, {"q": "'Poucos amigos' (negativo):", "ctx": "", "opts": ["few friends", "a few friends", "little friends", "a little friends"], "ans": 0, "exp": "Few = quase nenhum."}, {"q": "'Alguns livros' (positivo):", "ctx": "", "opts": ["a few books", "few books", "a little books", "little books"], "ans": 0, "exp": "A few + contável."}, {"q": "Com incontável usamos:", "ctx": "", "opts": ["little / a little", "few / a few", "many", "several"], "ans": 0, "exp": "Little water, little time."}, {"q": "'There is ___ we can do' (quase nada):", "ctx": "", "opts": ["little", "a little", "few", "a few"], "ans": 0, "exp": "Tom negativo."}, {"q": "'Quite a few' significa:", "ctx": "", "opts": ["bastante (muitos!)", "muito poucos", "quase nenhum", "exatamente alguns"], "ans": 0, "exp": "Pegadinha: quite a few = many!"}]$j$::jsonb),
('B2', 6022, $$Still, Yet, Already$$, $$ainda, já$$, $$⏱️$$, $$STILL = ainda continua (still working); YET = ainda não / já? (em negativas e perguntas, no fim); ALREADY = já (antes do esperado): I've already eaten.$$, $$Yet no FIM da frase: Have you finished yet? / I haven't finished yet.$$, $j$[{"en": "I'm still waiting for the bus.", "pt": "Ainda estou esperando o ônibus."}, {"en": "Have you had lunch yet?", "pt": "Você já almoçou?"}, {"en": "I've already seen this movie.", "pt": "Já vi esse filme."}]$j$::jsonb, $j$[{"q": "'Ainda estou trabalhando':", "ctx": "", "opts": ["I'm still working", "I'm yet working", "I'm already working", "Still I work"], "ans": 0, "exp": "Still = continua."}, {"q": "'Você já terminou?':", "ctx": "", "opts": ["Have you finished yet?", "Have you finished still?", "Did you finish already always?", "Have you yet finished?"], "ans": 0, "exp": "Yet no fim."}, {"q": "'Já comi' (antes do esperado):", "ctx": "", "opts": ["I've already eaten", "I've yet eaten", "I still ate", "I've eaten yet"], "ans": 0, "exp": "Already."}, {"q": "'Ainda não recebi':", "ctx": "", "opts": ["I haven't received it yet", "I haven't received it still", "I already haven't received", "I haven't yet still"], "ans": 0, "exp": "Not... yet."}, {"q": "Posição do already:", "ctx": "", "opts": ["antes do verbo principal", "no fim sempre", "no início sempre", "depois do objeto"], "ans": 0, "exp": "I've ALREADY seen."}, {"q": "'She STILL hasn't replied' expressa:", "ctx": "", "opts": ["impaciência (até agora nada!)", "alegria", "surpresa boa", "conclusão"], "ans": 0, "exp": "Still + negativa = ênfase."}]$j$::jsonb),
('B2', 6023, $$By × Until$$, $$prazo × duração$$, $$📆$$, $$BY = até (prazo final — a ação acontece ANTES ou NO momento): finish by Friday. UNTIL = até (duração contínua — a ação dura ATÉ lá): work until 6pm.$$, $$Entregar BY Friday (prazo) × trabalhar UNTIL Friday (continuidade).$$, $j$[{"en": "Please send the report by Monday.", "pt": "Envie o relatório até segunda (prazo)."}, {"en": "I'll be in the office until 7pm.", "pt": "Estarei no escritório até as 19h."}, {"en": "The store is open until midnight.", "pt": "A loja fica aberta até meia-noite."}]$j$::jsonb, $j$[{"q": "Prazo de entrega:", "ctx": "", "opts": ["by", "until", "for", "during"], "ans": 0, "exp": "By Friday = deadline."}, {"q": "'Fico aqui ATÉ as 5' (duração):", "ctx": "", "opts": ["until", "by", "for", "in"], "ans": 0, "exp": "Until = continua até."}, {"q": "'Pay ___ the end of the month' (prazo):", "ctx": "", "opts": ["by", "until", "during", "since"], "ans": 0, "exp": "Prazo = by."}, {"q": "'She slept ___ noon':", "ctx": "", "opts": ["until", "by", "for", "at"], "ans": 0, "exp": "Dormiu continuamente até."}, {"q": "'By the time you arrive...' =", "ctx": "", "opts": ["quando você chegar (já terá...)", "perto de você", "de sua parte", "com o tempo"], "ans": 0, "exp": "By the time + perfect."}, {"q": "Correto:", "ctx": "", "opts": ["I'll wait until you call", "I'll wait by you call", "I'll wait for you call time", "I'll wait during you call"], "ans": 0, "exp": "Espera contínua = until."}]$j$::jsonb),
('B2', 6024, $$During, While, For$$, $$durante × enquanto$$, $$🕰️$$, $$DURING + substantivo (during the meeting); WHILE + frase com verbo (while I was talking); FOR + duração em tempo (for two hours).$$, $$during the class ✅ | while the class ❌ | while I was in class ✅$$, $j$[{"en": "He fell asleep during the movie.", "pt": "Ele dormiu durante o filme."}, {"en": "She called while you were out.", "pt": "Ela ligou enquanto você estava fora."}, {"en": "We talked for three hours.", "pt": "Conversamos por três horas."}]$j$::jsonb, $j$[{"q": "'Durante a reunião':", "ctx": "", "opts": ["during the meeting", "while the meeting", "for the meeting time", "in during meeting"], "ans": 0, "exp": "During + substantivo."}, {"q": "'Enquanto eu dormia':", "ctx": "", "opts": ["while I was sleeping", "during I was sleeping", "for I was sleeping", "while my sleep verb"], "ans": 0, "exp": "While + oração."}, {"q": "'Por duas horas':", "ctx": "", "opts": ["for two hours", "during two hours", "while two hours", "since two hours"], "ans": 0, "exp": "For + duração."}, {"q": "Depois de DURING vem:", "ctx": "", "opts": ["substantivo", "oração com verbo", "duração numérica", "adjetivo"], "ans": 0, "exp": "During the trip."}, {"q": "'Choveu durante a noite':", "ctx": "", "opts": ["It rained during the night", "It rained while the night", "It rained for the night", "It rained in while night"], "ans": 0, "exp": "During."}, {"q": "'Meanwhile' =", "ctx": "", "opts": ["enquanto isso", "no meio do caminho", "de vez em quando", "há muito tempo"], "ans": 0, "exp": "Conector de simultaneidade."}]$j$::jsonb),
('B2', 6025, $$As × Like$$, $$como (de dois jeitos)$$, $$🎭$$, $$LIKE + substantivo = parecido com (sings like an angel). AS + função/cargo = na condição de (works as a teacher). AS + oração = como/conforme (as I said).$$, $$He works AS a waiter (é o emprego dele) × he acts LIKE a boss (parece, mas não é).$$, $j$[{"en": "She sings like a professional.", "pt": "Ela canta como uma profissional (parece)."}, {"en": "He works as an engineer.", "pt": "Ele trabalha como engenheiro (é)."}, {"en": "As I said, the meeting is at 3.", "pt": "Como eu disse, a reunião é às 3."}]$j$::jsonb, $j$[{"q": "'Trabalha como médico' (profissão):", "ctx": "", "opts": ["as a doctor", "like a doctor", "as doctor like", "such a doctor"], "ans": 0, "exp": "AS = função real."}, {"q": "'Chora como um bebê' (comparação):", "ctx": "", "opts": ["like a baby", "as a baby", "as baby does only", "such baby"], "ans": 0, "exp": "LIKE = parecido."}, {"q": "'Como eu mencionei':", "ctx": "", "opts": ["As I mentioned", "Like I mentioned (formal)", "As mentioning", "Like mentioned I"], "ans": 0, "exp": "As + oração (formal)."}, {"q": "'Use a caixa como mesa' (improviso):", "ctx": "", "opts": ["as a table", "like a table", "for like table", "such as table"], "ans": 0, "exp": "Funciona de mesa = as."}, {"q": "'Parece o pai' (aparência):", "ctx": "", "opts": ["He looks like his father", "He looks as his father", "He looks such his father", "He alike his father"], "ans": 0, "exp": "Look like."}, {"q": "'Such as' =", "ctx": "", "opts": ["como por exemplo", "tão como", "assim seja", "tanto quanto"], "ans": 0, "exp": "Fruits such as mango..."}]$j$::jsonb),
('B2', 6026, $$Even though × Even if$$, $$concessão real × hipotética$$, $$🧗$$, $$EVEN THOUGH + fato real (embora — aconteceu mesmo): Even though it rained, we went. EVEN IF + hipótese (mesmo que — talvez nem aconteça): Even if it rains, we'll go.$$, $$Even though = fato. Even if = suposição. O jogo muda completamente.$$, $j$[{"en": "Even though he was tired, he kept working.", "pt": "Embora estivesse cansado, continuou trabalhando."}, {"en": "Even if it costs a fortune, I'll buy it.", "pt": "Mesmo que custe uma fortuna, vou comprar."}, {"en": "She smiled even though she was sad.", "pt": "Ela sorriu embora estivesse triste."}]$j$::jsonb, $j$[{"q": "Fato real (aconteceu):", "ctx": "", "opts": ["even though", "even if", "only if", "as if"], "ans": 0, "exp": "Even though it RAINED..."}, {"q": "Hipótese (talvez):", "ctx": "", "opts": ["even if", "even though", "although really", "despite that"], "ans": 0, "exp": "Even if it rains..."}, {"q": "'Mesmo que você pague, não vou':", "ctx": "", "opts": ["Even if you pay, I won't go", "Even though you pay, I won't", "Despite you pay", "Although pay you"], "ans": 0, "exp": "Hipótese = even if."}, {"q": "'Embora eu more perto, chego atrasado':", "ctx": "", "opts": ["Even though I live near, I'm late", "Even if I live near", "If even I live near", "As if I live near"], "ans": 0, "exp": "Fato = even though."}, {"q": "'As if' =", "ctx": "", "opts": ["como se (irreal)", "mesmo assim", "e se", "até se"], "ans": 0, "exp": "He acts as if he knew."}, {"q": "Even though ≈", "ctx": "", "opts": ["although (mais forte)", "because", "unless", "therefore"], "ans": 0, "exp": "Embora, com ênfase."}]$j$::jsonb),
('B2', 6027, $$Phrasal verbs com GET$$, $$get up, get over, get along$$, $$🚪$$, $$Os GET essenciais: get up (levantar), get along with (dar-se bem), get back (voltar), get in/out (entrar/sair), get on/off (embarcar/descer), get together (reunir-se).$$, $$Get on the bus (ônibus/trem/avião) mas get in the car (carro/táxi)!$$, $j$[{"en": "I get up at 6 every day.", "pt": "Levanto às 6 todo dia."}, {"en": "Do you get along with your boss?", "pt": "Você se dá bem com seu chefe?"}, {"en": "Let's get together this weekend!", "pt": "Vamos nos reunir este fim de semana!"}]$j$::jsonb, $j$[{"q": "'Levantar da cama':", "ctx": "", "opts": ["get up", "get off", "get out only", "get on"], "ans": 0, "exp": "Get up at 7."}, {"q": "'Dar-se bem com':", "ctx": "", "opts": ["get along with", "get up with", "get over with", "get back with"], "ans": 0, "exp": "Get along."}, {"q": "'Embarcar no ônibus':", "ctx": "", "opts": ["get on the bus", "get in the bus", "get up the bus", "get at the bus"], "ans": 0, "exp": "On = transportes grandes."}, {"q": "'Entrar no carro':", "ctx": "", "opts": ["get in the car", "get on the car", "get up the car", "get to car"], "ans": 0, "exp": "In = carro/táxi."}, {"q": "'Voltar (de viagem)':", "ctx": "", "opts": ["get back", "get again", "get return", "get behind"], "ans": 0, "exp": "When do you get back?"}, {"q": "'Reunir-se':", "ctx": "", "opts": ["get together", "get union", "get meet", "get group"], "ans": 0, "exp": "Get together."}]$j$::jsonb),
('B2', 6028, $$Phrasal verbs com PUT$$, $$put off, put on, put up with$$, $$📦$$, $$PUT resolve tudo: put on (vestir), put off (adiar), put up with (aguentar), put away (guardar), put out (apagar fogo), put through (transferir ligação).$$, $$"I can't put up with this noise" = não aguento mais esse barulho.$$, $j$[{"en": "Put on your jacket — it's cold.", "pt": "Vista a jaqueta — está frio."}, {"en": "They put off the meeting again.", "pt": "Adiaram a reunião de novo."}, {"en": "I won't put up with this behavior.", "pt": "Não vou tolerar esse comportamento."}]$j$::jsonb, $j$[{"q": "'Vestir':", "ctx": "", "opts": ["put on", "put off", "put in", "put away"], "ans": 0, "exp": "Put on your shoes."}, {"q": "'Adiar':", "ctx": "", "opts": ["put off", "put on", "put out", "put down"], "ans": 0, "exp": "Put off = postpone."}, {"q": "'Aguentar/tolerar':", "ctx": "", "opts": ["put up with", "put on with", "put off with", "put over with"], "ans": 0, "exp": "3 partes!"}, {"q": "'Guardar (no lugar)':", "ctx": "", "opts": ["put away", "put behind", "put out", "put along"], "ans": 0, "exp": "Put your toys away."}, {"q": "'Apagar (fogo/cigarro)':", "ctx": "", "opts": ["put out", "put off", "put down", "put over"], "ans": 0, "exp": "Put out the fire."}, {"q": "'Transferir a ligação':", "ctx": "", "opts": ["put you through", "put you over", "put you across", "put you along"], "ans": 0, "exp": "I'll put you through."}]$j$::jsonb),
('B2', 6029, $$Phrasal verbs com GO$$, $$go on, go out, go off$$, $$🚦$$, $$GO em movimento: go on (continuar/acontecer), go out (sair/namorar), go off (disparar alarme/estragar), go up/down (subir/descer preços), go over (revisar), go without (ficar sem).$$, $$What's going on? = O que está acontecendo? — talvez o phrasal mais dito do inglês.$$, $j$[{"en": "What's going on here?", "pt": "O que está acontecendo aqui?"}, {"en": "The alarm went off at 5am.", "pt": "O alarme disparou às 5 da manhã."}, {"en": "Prices went up again this month.", "pt": "Os preços subiram de novo este mês."}]$j$::jsonb, $j$[{"q": "'Continuar':", "ctx": "", "opts": ["go on", "go out", "go off", "go under"], "ans": 0, "exp": "Go on = continue."}, {"q": "'O alarme disparou':", "ctx": "", "opts": ["went off", "went out", "went on", "went away"], "ans": 0, "exp": "Go off."}, {"q": "'Sair (à noite)':", "ctx": "", "opts": ["go out", "go off", "go on", "go over"], "ans": 0, "exp": "Going out tonight?"}, {"q": "'O leite estragou':", "ctx": "", "opts": ["went off", "went down", "went out", "went over"], "ans": 0, "exp": "Go off = estragar (BrE)."}, {"q": "'Revisar (o material)':", "ctx": "", "opts": ["go over", "go without", "go against", "go into fast"], "ans": 0, "exp": "Go over the notes."}, {"q": "'Ficar sem (café)':", "ctx": "", "opts": ["go without", "go outside", "go off from", "go away from"], "ans": 0, "exp": "Go without coffee."}]$j$::jsonb),
('B2', 6030, $$Phrasal verbs com LOOK$$, $$look for, look after, look up$$, $$🔍$$, $$LOOK além do olhar: look for (procurar), look after (cuidar de), look up (pesquisar), look forward to (aguardar ansioso), look into (investigar), look out (cuidado!).$$, $$Look forward to + -ing: I look forward to hearing from you (fecho clássico de e-mail).$$, $j$[{"en": "I'm looking for my keys.", "pt": "Estou procurando minhas chaves."}, {"en": "She looks after her grandmother.", "pt": "Ela cuida da avó."}, {"en": "Look up the word in the dictionary.", "pt": "Procure a palavra no dicionário."}]$j$::jsonb, $j$[{"q": "'Procurar':", "ctx": "", "opts": ["look for", "look after", "look up to", "look out"], "ans": 0, "exp": "Looking for a job."}, {"q": "'Cuidar de':", "ctx": "", "opts": ["look after", "look for", "look at", "look over"], "ans": 0, "exp": "Look after kids."}, {"q": "'Pesquisar (palavra/informação)':", "ctx": "", "opts": ["look up", "look down", "look in", "look about"], "ans": 0, "exp": "Look it up!"}, {"q": "'Aguardar ansiosamente':", "ctx": "", "opts": ["look forward to", "look ahead to", "look front to", "look for to"], "ans": 0, "exp": "+ -ing!"}, {"q": "'Investigar':", "ctx": "", "opts": ["look into", "look inside", "look under", "look behind"], "ans": 0, "exp": "Police are looking into it."}, {"q": "'Cuidado!':", "ctx": "", "opts": ["Look out!", "Look up!", "Look on!", "Look in!"], "ans": 0, "exp": "Watch out = look out."}]$j$::jsonb),
('B2', 6031, $$Phrasal verbs com GIVE$$, $$give up, give back, give in$$, $$🎁$$, $$GIVE generoso: give up (desistir), give back (devolver), give in (ceder), give away (doar/entregar segredo), give out (distribuir/acabar).$$, $$Never give up! — o phrasal verb motivacional oficial.$$, $j$[{"en": "Don't give up on your dreams!", "pt": "Não desista dos seus sonhos!"}, {"en": "Can you give back my pen?", "pt": "Pode devolver minha caneta?"}, {"en": "She gave away all her old clothes.", "pt": "Ela doou todas as roupas antigas."}]$j$::jsonb, $j$[{"q": "'Desistir':", "ctx": "", "opts": ["give up", "give in only", "give out", "give away"], "ans": 0, "exp": "Give up smoking."}, {"q": "'Devolver':", "ctx": "", "opts": ["give back", "give again", "give return", "give off"], "ans": 0, "exp": "Give it back!"}, {"q": "'Ceder (à pressão)':", "ctx": "", "opts": ["give in", "give on", "give under", "give low"], "ans": 0, "exp": "He finally gave in."}, {"q": "'Doar':", "ctx": "", "opts": ["give away", "give far", "give without", "give from"], "ans": 0, "exp": "Give away clothes."}, {"q": "'Distribuir (panfletos)':", "ctx": "", "opts": ["give out", "give around", "give over", "give onto"], "ans": 0, "exp": "Give out flyers."}, {"q": "'Entregar o segredo sem querer':", "ctx": "", "opts": ["give it away", "give it back", "give it in", "give it off"], "ans": 0, "exp": "Don't give it away!"}]$j$::jsonb),
('B2', 6032, $$Phrasal verbs com BRING$$, $$bring up, bring back$$, $$🧳$$, $$BRING que carrega sentidos: bring up (criar filhos/levantar assunto), bring back (trazer de volta/relembrar), bring about (causar), bring out (lançar), bring along (trazer junto).$$, $$She was brought up by her grandparents = foi criada pelos avós.$$, $j$[{"en": "Don't bring up politics at dinner.", "pt": "Não levante política no jantar."}, {"en": "This song brings back memories.", "pt": "Essa música traz lembranças."}, {"en": "They brought out a new model.", "pt": "Lançaram um modelo novo."}]$j$::jsonb, $j$[{"q": "'Criar (filhos)':", "ctx": "", "opts": ["bring up", "bring on", "bring down", "grow up others"], "ans": 0, "exp": "Bring up children."}, {"q": "'Levantar um assunto':", "ctx": "", "opts": ["bring up", "bring out", "bring off", "bring over"], "ans": 0, "exp": "Bring up a topic."}, {"q": "'Trazer lembranças':", "ctx": "", "opts": ["bring back", "bring again", "bring behind", "bring past"], "ans": 0, "exp": "Brings back memories."}, {"q": "'Causar (mudança)':", "ctx": "", "opts": ["bring about", "bring around town", "bring beside", "bring upon always"], "ans": 0, "exp": "Bring about change."}, {"q": "'Lançar (produto)':", "ctx": "", "opts": ["bring out", "bring up new", "bring away", "bring forth only"], "ans": 0, "exp": "Bring out an album."}, {"q": "'Traga um amigo junto':", "ctx": "", "opts": ["bring a friend along", "bring a friend about", "bring a friend behind", "bring a friend away"], "ans": 0, "exp": "Bring along."}]$j$::jsonb),
('B2', 6033, $$Phrasal verbs com FALL$$, $$fall apart, fall out$$, $$🍂$$, $$FALL além da queda: fall apart (desmoronar), fall out (brigar/romper), fall behind (ficar para trás), fall for (apaixonar-se/cair no golpe), fall through (fracassar — plano).$$, $$"I fell for it" = caí feito um pato. "I fell for her" = me apaixonei. Contexto!$$, $j$[{"en": "Their marriage fell apart.", "pt": "O casamento deles desmoronou."}, {"en": "Don't fall behind with your studies.", "pt": "Não fique para trás nos estudos."}, {"en": "Our travel plans fell through.", "pt": "Nossos planos de viagem furaram."}]$j$::jsonb, $j$[{"q": "'Desmoronar/despedaçar':", "ctx": "", "opts": ["fall apart", "fall away", "fall down only", "fall aside"], "ans": 0, "exp": "Everything fell apart."}, {"q": "'Brigar (amizade rompida)':", "ctx": "", "opts": ["fall out", "fall off", "fall over", "fall against"], "ans": 0, "exp": "They fell out."}, {"q": "'Ficar para trás':", "ctx": "", "opts": ["fall behind", "fall back home", "fall late", "fall under"], "ans": 0, "exp": "Fall behind at school."}, {"q": "'Cair no golpe':", "ctx": "", "opts": ["fall for it", "fall on it", "fall by it", "fall at it"], "ans": 0, "exp": "Don't fall for it!"}, {"q": "'Apaixonar-se por':", "ctx": "", "opts": ["fall for", "fall with", "fall to", "fall about"], "ans": 0, "exp": "He fell for her."}, {"q": "'O plano furou':", "ctx": "", "opts": ["fell through", "fell out of sky", "fell over", "fell along"], "ans": 0, "exp": "Fall through."}]$j$::jsonb),
('B2', 6034, $$Phrasal verbs com HOLD$$, $$hold on, hold up$$, $$✊$$, $$HOLD que segura a conversa: hold on (espere/aguente), hold up (atrasar/assaltar), hold back (conter), hold out (resistir), hold onto (agarrar-se a).$$, $$Hold on! serve para telefone, elevador e crise existencial.$$, $j$[{"en": "Hold on a second, please.", "pt": "Espere um segundo, por favor."}, {"en": "Sorry, I was held up in traffic.", "pt": "Desculpe, fiquei preso no trânsito."}, {"en": "She couldn't hold back her tears.", "pt": "Ela não conseguiu conter as lágrimas."}]$j$::jsonb, $j$[{"q": "'Espere um pouco':", "ctx": "", "opts": ["hold on", "hold off forever", "hold down", "hold away"], "ans": 0, "exp": "Hold on!"}, {"q": "'Fui atrasado (trânsito)':", "ctx": "", "opts": ["held up", "held on", "held out", "held over"], "ans": 0, "exp": "Held up in traffic."}, {"q": "'Conter (lágrimas/raiva)':", "ctx": "", "opts": ["hold back", "hold behind", "hold low", "hold inside out"], "ans": 0, "exp": "Hold back tears."}, {"q": "'Resistir (não ceder)':", "ctx": "", "opts": ["hold out", "hold away", "hold against", "hold from"], "ans": 0, "exp": "Hold out for more."}, {"q": "'Agarre-se a (não solte)':", "ctx": "", "opts": ["hold onto", "hold at", "hold beside", "hold along"], "ans": 0, "exp": "Hold onto the rail."}, {"q": "'Hold up' também é:", "ctx": "", "opts": ["assaltar", "elogiar", "construir", "pintar"], "ans": 0, "exp": "A bank hold-up."}]$j$::jsonb),
('B2', 6035, $$Say, Tell, Speak, Talk$$, $$os 4 falares$$, $$🗣️$$, $$SAY algo (say a word); TELL alguém (tell me); SPEAK idioma/formal (speak English); TALK conversa (talk to friends). Tell SEMPRE tem ouvinte: tell HIM, tell US.$$, $$say me ❌ → tell me ✅ | tell to me ❌ → tell me ✅$$, $j$[{"en": "She said something interesting.", "pt": "Ela disse algo interessante."}, {"en": "Can you tell me the time?", "pt": "Pode me dizer as horas?"}, {"en": "Do you speak Spanish?", "pt": "Você fala espanhol?"}]$j$::jsonb, $j$[{"q": "'___ me a diferença':", "ctx": "", "opts": ["Tell", "Say", "Speak", "Talk"], "ans": 0, "exp": "Tell + pessoa."}, {"q": "'Falar inglês':", "ctx": "", "opts": ["speak English", "talk English", "say English", "tell English"], "ans": 0, "exp": "Speak + idioma."}, {"q": "'Conversar com amigos':", "ctx": "", "opts": ["talk to friends", "say to friends", "speak friends", "tell at friends"], "ans": 0, "exp": "Talk = conversa."}, {"q": "Correto:", "ctx": "", "opts": ["She told me the truth", "She said me the truth", "She talked me the truth", "She spoke me truth"], "ans": 0, "exp": "Tell + objeto."}, {"q": "'Dizer a verdade':", "ctx": "", "opts": ["tell the truth", "say the true", "speak the truth always", "talk truth"], "ans": 0, "exp": "Tell the truth (fixo)."}, {"q": "'Contar uma história':", "ctx": "", "opts": ["tell a story", "say a story", "speak a story", "talk a story"], "ans": 0, "exp": "Tell a story/joke/lie."}]$j$::jsonb),
('B2', 6036, $$Bring, Take, Fetch$$, $$trazer × levar$$, $$🔄$$, $$Direção importa: BRING = trazer PARA CÁ (bring it here); TAKE = levar PARA LÁ (take it there); FETCH = ir buscar e voltar (o que o cachorro faz!).$$, $$Na dúvida: bring vem, take vai.$$, $j$[{"en": "Bring your notebook to class.", "pt": "Traga seu caderno para a aula."}, {"en": "Take this letter to the post office.", "pt": "Leve esta carta ao correio."}, {"en": "Can you fetch the kids from school?", "pt": "Pode buscar as crianças na escola?"}]$j$::jsonb, $j$[{"q": "'Traga PARA CÁ':", "ctx": "", "opts": ["bring", "take", "fetch", "carry away"], "ans": 0, "exp": "Bring here."}, {"q": "'Leve PARA LÁ':", "ctx": "", "opts": ["take", "bring", "fetch", "hold"], "ans": 0, "exp": "Take there."}, {"q": "'Ir buscar (e voltar)':", "ctx": "", "opts": ["fetch", "bring only", "take only", "reach"], "ans": 0, "exp": "Fetch = busca completa."}, {"q": "'___ um casaco na viagem' (você vai):", "ctx": "", "opts": ["Take", "Bring", "Fetch", "Get here"], "ans": 0, "exp": "Você LEVA."}, {"q": "'___ me um copo d'água' (vem até mim):", "ctx": "", "opts": ["Bring", "Take", "Push", "Move"], "ans": 0, "exp": "Traz para cá."}, {"q": "O cachorro brinca de:", "ctx": "", "opts": ["fetch", "bring", "take", "carry"], "ans": 0, "exp": "Play fetch!"}]$j$::jsonb),
('B2', 6037, $$Come × Go$$, $$vir × ir (com pegadinha)$$, $$🧭$$, $$COME = em direção a quem fala/ouve; GO = para longe. Pegadinha: em convites, o inglês usa COME mesmo quando 'vamos': I'm coming to your party (vou à sua festa!).$$, $$"Dinner's ready!" → "I'm coming!" (indo na direção de quem chamou).$$, $j$[{"en": "Come here, please!", "pt": "Venha aqui, por favor!"}, {"en": "I'm coming to your party on Saturday.", "pt": "Vou à sua festa no sábado."}, {"en": "She goes to the gym every day.", "pt": "Ela vai à academia todo dia."}]$j$::jsonb, $j$[{"q": "Alguém te chama. Você responde:", "ctx": "", "opts": ["I'm coming!", "I'm going!", "I go!", "I come there!"], "ans": 0, "exp": "Na direção de quem chamou."}, {"q": "'Vou à SUA casa' (do ouvinte):", "ctx": "", "opts": ["I'll come to your house", "I'll go to your house", "I'll arrive your house", "I'll reach at your house"], "ans": 0, "exp": "Come = direção do ouvinte."}, {"q": "'Ir embora':", "ctx": "", "opts": ["go away", "come away", "go here", "come along"], "ans": 0, "exp": "Para longe = go."}, {"q": "'Come along' =", "ctx": "", "opts": ["venha junto", "venha depois", "vá sozinho", "chegue cedo"], "ans": 0, "exp": "Junte-se a nós."}, {"q": "'How's it coming along?' =", "ctx": "", "opts": ["como está progredindo?", "como você veio?", "por onde anda?", "quando chega?"], "ans": 0, "exp": "Progresso."}, {"q": "'Vai e volta muito' (trabalho):", "ctx": "", "opts": ["commute", "come and come", "go and go", "travel forever"], "ans": 0, "exp": "Commute = trajeto diário."}]$j$::jsonb),
('B2', 6038, $$Borrow × Lend$$, $$pegar × dar emprestado$$, $$🤲$$, $$BORROW = pegar emprestado (você recebe): Can I borrow your pen? LEND = emprestar (você dá): Can you lend me your pen? Lend + pessoa + coisa.$$, $$Se a coisa VEM para você: borrow. Se a coisa SAI de você: lend.$$, $j$[{"en": "Can I borrow your umbrella?", "pt": "Posso pegar seu guarda-chuva emprestado?"}, {"en": "She lent me her car for the weekend.", "pt": "Ela me emprestou o carro no fim de semana."}, {"en": "I never lend money to friends.", "pt": "Nunca empresto dinheiro a amigos."}]$j$::jsonb, $j$[{"q": "'PEGAR emprestado':", "ctx": "", "opts": ["borrow", "lend", "loan to", "rent always"], "ans": 0, "exp": "Borrow = receber."}, {"q": "'DAR emprestado':", "ctx": "", "opts": ["lend", "borrow", "take", "keep"], "ans": 0, "exp": "Lend = dar."}, {"q": "'Posso pegar sua caneta?':", "ctx": "", "opts": ["Can I borrow your pen?", "Can I lend your pen?", "Can you borrow me?", "Can I loan you pen?"], "ans": 0, "exp": "Você recebe = borrow."}, {"q": "'Você me empresta R$10?':", "ctx": "", "opts": ["Can you lend me R$10?", "Can you borrow me R$10?", "Can I lend you R$10?", "Do you borrow R$10?"], "ans": 0, "exp": "Você dá = lend."}, {"q": "Passado de lend:", "ctx": "", "opts": ["lent", "lended", "lond", "leant only"], "ans": 0, "exp": "Lend-lent-lent."}, {"q": "'Loan' (substantivo) =", "ctx": "", "opts": ["empréstimo", "sozinho", "salário", "dívida paga"], "ans": 0, "exp": "A bank loan."}]$j$::jsonb),
('B2', 6039, $$Remember × Remind$$, $$lembrar × fazer lembrar$$, $$🎗️$$, $$REMEMBER = lembrar sozinho (I remember his name). REMIND = alguém/algo te faz lembrar (Remind me to call / This song reminds me of you).$$, $$Remind SEMPRE tem objeto: remind ME, remind HER. Sem objeto, use remember.$$, $j$[{"en": "I can't remember her name.", "pt": "Não consigo lembrar o nome dela."}, {"en": "Remind me to buy milk, please.", "pt": "Me lembre de comprar leite, por favor."}, {"en": "This place reminds me of my hometown.", "pt": "Este lugar me lembra minha cidade natal."}]$j$::jsonb, $j$[{"q": "'Lembrar sozinho':", "ctx": "", "opts": ["remember", "remind", "memory", "recall me"], "ans": 0, "exp": "I remember!"}, {"q": "'Me faça lembrar':", "ctx": "", "opts": ["remind me", "remember me", "memory me", "recall to me"], "ans": 0, "exp": "Remind + pessoa."}, {"q": "'Essa música me lembra você':", "ctx": "", "opts": ["reminds me of you", "remembers me of you", "reminds me you", "remembers you to me"], "ans": 0, "exp": "Remind of."}, {"q": "Correto:", "ctx": "", "opts": ["Remind me to pay the bill", "Remember me to pay", "Remind to pay me", "Remember to me pay"], "ans": 0, "exp": "Remind me to..."}, {"q": "'Do you remember ___ him?' (passado):", "ctx": "", "opts": ["meeting", "to meet", "meet", "met"], "ans": 0, "exp": "Remember + -ing = memória."}, {"q": "'Set a reminder' =", "ctx": "", "opts": ["criar um lembrete", "lembrar de novo", "esquecer", "adiar"], "ans": 0, "exp": "No celular!"}]$j$::jsonb),
('B2', 6040, $$Lose × Miss$$, $$perder (de dois jeitos)$$, $$🧦$$, $$LOSE = perder posse/jogo (lose keys, lose a match). MISS = perder por não estar lá (miss the bus, miss a class) e sentir falta (I miss you).$$, $$Perdeu o ônibus = missed the bus. Perdeu as chaves = lost the keys.$$, $j$[{"en": "I lost my wallet yesterday.", "pt": "Perdi minha carteira ontem."}, {"en": "Hurry up or we'll miss the train!", "pt": "Corre ou vamos perder o trem!"}, {"en": "I miss my family so much.", "pt": "Sinto tanta falta da minha família."}]$j$::jsonb, $j$[{"q": "'Perdi as chaves':", "ctx": "", "opts": ["lost my keys", "missed my keys", "losed my keys", "left my keys lost"], "ans": 0, "exp": "Posse = lose."}, {"q": "'Perdi o voo':", "ctx": "", "opts": ["missed the flight", "lost the flight", "failed the flight", "dropped the flight"], "ans": 0, "exp": "Não estava lá = miss."}, {"q": "'Sinto sua falta':", "ctx": "", "opts": ["I miss you", "I lose you", "I lack you", "I want you back only"], "ans": 0, "exp": "Miss = saudade."}, {"q": "'Perdemos o jogo (derrota)':", "ctx": "", "opts": ["lost the game", "missed the game", "failed game", "dropped the game"], "ans": 0, "exp": "Derrota = lose."}, {"q": "'Perdi a aula (faltei)':", "ctx": "", "opts": ["missed the class", "lost the class", "skipped lost class", "failed class"], "ans": 0, "exp": "Miss a class."}, {"q": "'Get lost!' =", "ctx": "", "opts": ["cai fora!", "perca-se com cuidado", "ache o caminho", "boa sorte"], "ans": 0, "exp": "Grosseria: some!"}]$j$::jsonb),
('B2', 6041, $$Look, See, Watch$$, $$3 jeitos de ver$$, $$📺$$, $$SEE = ver sem esforço (I see a bird); LOOK = olhar direcionado (look at this); WATCH = assistir com atenção prolongada (watch TV). See a movie no cinema, watch TV em casa!$$, $$see TV ❌ → watch TV ✅ | Look! (olha!) × See? (viu?)$$, $j$[{"en": "Did you see that?", "pt": "Você viu aquilo?"}, {"en": "Look at this photo!", "pt": "Olha esta foto!"}, {"en": "We watched a series all night.", "pt": "Assistimos a uma série a noite toda."}]$j$::jsonb, $j$[{"q": "'Assistir TV':", "ctx": "", "opts": ["watch TV", "see TV", "look TV", "view TV always"], "ans": 0, "exp": "Watch = atenção contínua."}, {"q": "'Olha isso!':", "ctx": "", "opts": ["Look at this!", "See this now!", "Watch this photo!", "Sight this!"], "ans": 0, "exp": "Look at."}, {"q": "'Vi um pássaro' (sem querer):", "ctx": "", "opts": ["saw", "watched", "looked", "stared"], "ans": 0, "exp": "See = percepção."}, {"q": "No cinema, os nativos dizem:", "ctx": "", "opts": ["see a movie", "watch a movie at cinema only", "look a movie", "observe a movie"], "ans": 0, "exp": "See a movie (no cinema)."}, {"q": "'Let me see' =", "ctx": "", "opts": ["deixa eu pensar/ver", "me assista", "olhe para mim", "veja você"], "ans": 0, "exp": "Pausa para pensar."}, {"q": "'Watch out!' =", "ctx": "", "opts": ["cuidado!", "assista fora!", "olhe o relógio!", "espere!"], "ans": 0, "exp": "= Look out!"}]$j$::jsonb),
('B2', 6042, $$Hear × Listen$$, $$ouvir × escutar$$, $$🎧$$, $$HEAR = ouvir sem intenção (o som chega): I heard a noise. LISTEN (to) = escutar com atenção (você escolhe): listen to music. Listen sempre com TO antes do objeto!$$, $$listen music ❌ → listen TO music ✅$$, $j$[{"en": "Did you hear that noise?", "pt": "Você ouviu aquele barulho?"}, {"en": "I love listening to podcasts.", "pt": "Adoro escutar podcasts."}, {"en": "Sorry, I wasn't listening.", "pt": "Desculpa, eu não estava prestando atenção."}]$j$::jsonb, $j$[{"q": "'Escutar música':", "ctx": "", "opts": ["listen to music", "hear music actively", "listen music", "hear to music"], "ans": 0, "exp": "Listen TO."}, {"q": "'Ouvi um grito' (sem querer):", "ctx": "", "opts": ["heard", "listened", "listened to", "sounded"], "ans": 0, "exp": "Hear = chega ao ouvido."}, {"q": "Correto:", "ctx": "", "opts": ["Listen to me!", "Hear to me!", "Listen me!", "Hear me up!"], "ans": 0, "exp": "Listen TO me."}, {"q": "'I can't hear you' =", "ctx": "", "opts": ["não consigo te ouvir", "não quero te escutar", "não te entendo nunca", "não presto atenção"], "ans": 0, "exp": "Problema físico/volume."}, {"q": "'Hearing' (substantivo) =", "ctx": "", "opts": ["audição", "escuta ativa", "fone", "surdez"], "ans": 0, "exp": "Sentido da audição."}, {"q": "'I hear you' (idiomático) =", "ctx": "", "opts": ["te entendo/te ouço", "estou surdo", "fale mais alto", "repita"], "ans": 0, "exp": "Empatia: entendi seu ponto."}]$j$::jsonb),
('B2', 6043, $$Travel, Trip, Journey$$, $$viajar sem errar$$, $$✈️$$, $$TRAVEL = o ato de viajar (verbo/incontável: I love travel). TRIP = a viagem específica, com ida e volta (a business trip). JOURNEY = o trajeto em si (a 6-hour journey).$$, $$a travel ❌ → a trip ✅. How was your trip? = como foi a viagem?$$, $j$[{"en": "I love traveling around Brazil.", "pt": "Adoro viajar pelo Brasil."}, {"en": "She's on a business trip.", "pt": "Ela está em viagem de negócios."}, {"en": "The journey takes six hours by bus.", "pt": "O trajeto leva seis horas de ônibus."}]$j$::jsonb, $j$[{"q": "'Uma viagem' (contável):", "ctx": "", "opts": ["a trip", "a travel", "a traveling", "a tour always"], "ans": 0, "exp": "Trip!"}, {"q": "'Viagem de negócios':", "ctx": "", "opts": ["business trip", "business travel one", "business journey only", "business tour"], "ans": 0, "exp": "Business trip."}, {"q": "O TRAJETO de 8 horas:", "ctx": "", "opts": ["journey", "trip whole", "travel", "voyage only"], "ans": 0, "exp": "Journey = percurso."}, {"q": "'Adoro viajar':", "ctx": "", "opts": ["I love traveling", "I love a travel", "I love trip", "I love journeys only"], "ans": 0, "exp": "Travel como atividade."}, {"q": "'Voyage' é usado para:", "ctx": "", "opts": ["viagens longas de navio/espaço", "qualquer ônibus", "metrô", "caminhada"], "ans": 0, "exp": "Bon voyage!"}, {"q": "'How was your ___?' (recepção no destino):", "ctx": "", "opts": ["trip", "travel", "voyage daily", "commute"], "ans": 0, "exp": "How was your trip?"}]$j$::jsonb),
('B2', 6044, $$Job, Work, Career$$, $$trabalho aos três$$, $$💼$$, $$WORK = trabalho em geral (incontável: I have work to do). JOB = o emprego específico (contável: a good job). CAREER = a carreira, trajetória de anos.$$, $$a work ❌ → a job ✅. What do you do? = qual é seu trabalho?$$, $j$[{"en": "I have a lot of work today.", "pt": "Tenho muito trabalho hoje."}, {"en": "She got a new job at the bank.", "pt": "Ela conseguiu um emprego novo no banco."}, {"en": "He had a brilliant career in law.", "pt": "Ele teve uma carreira brilhante no direito."}]$j$::jsonb, $j$[{"q": "'Um emprego' (contável):", "ctx": "", "opts": ["a job", "a work", "a career piece", "an employ"], "ans": 0, "exp": "Job."}, {"q": "'Tenho trabalho a fazer':", "ctx": "", "opts": ["work to do", "a work to do", "job to do it", "works to do"], "ans": 0, "exp": "Work incontável."}, {"q": "Trajetória de 20 anos:", "ctx": "", "opts": ["career", "job", "work", "task"], "ans": 0, "exp": "Career."}, {"q": "'Estou no trabalho (local)':", "ctx": "", "opts": ["at work", "in work place", "on the job place", "at working"], "ans": 0, "exp": "At work."}, {"q": "'Job interview' =", "ctx": "", "opts": ["entrevista de emprego", "conversa de trabalho", "avaliação anual", "demissão"], "ans": 0, "exp": "Entrevista."}, {"q": "'It's hard work' =", "ctx": "", "opts": ["é trabalhoso", "é um emprego difícil", "é carreira dura", "é raro"], "ans": 0, "exp": "Esforço."}]$j$::jsonb),
('B2', 6045, $$Fun × Funny$$, $$divertido × engraçado$$, $$😄$$, $$FUN = divertido/prazeroso (the party was fun). FUNNY = engraçado, que faz rir (a funny joke) — ou estranho (a funny smell!). A festa é fun; o palhaço é funny.$$, $$"The party was funny" soa como se a festa fosse... esquisita. Cuidado!$$, $j$[{"en": "The trip was so much fun!", "pt": "A viagem foi muito divertida!"}, {"en": "He tells really funny jokes.", "pt": "Ele conta piadas muito engraçadas."}, {"en": "There's a funny smell in here.", "pt": "Tem um cheiro estranho aqui."}]$j$::jsonb, $j$[{"q": "'A festa foi divertida':", "ctx": "", "opts": ["The party was fun", "The party was funny", "The party was laugh", "The party was joke"], "ans": 0, "exp": "Fun = prazer."}, {"q": "'Piada engraçada':", "ctx": "", "opts": ["funny joke", "fun joke", "laughing joke", "played joke"], "ans": 0, "exp": "Funny = faz rir."}, {"q": "'Funny' também significa:", "ctx": "", "opts": ["estranho", "chato", "rápido", "caro"], "ans": 0, "exp": "A funny noise = barulho esquisito."}, {"q": "'Have fun!' =", "ctx": "", "opts": ["divirta-se!", "seja engraçado!", "ria!", "boa sorte!"], "ans": 0, "exp": "Aproveite!"}, {"q": "'Ele é engraçado':", "ctx": "", "opts": ["He's funny", "He's fun person only", "He's laugh", "He's joke"], "ans": 0, "exp": "Faz rir = funny."}, {"q": "'Make fun of' =", "ctx": "", "opts": ["zombar de", "divertir alguém", "fazer graça saudável", "elogiar"], "ans": 0, "exp": "Tirar sarro."}]$j$::jsonb),
('B2', 6046, $$Sensible × Sensitive$$, $$falsos gêmeos$$, $$🎭$$, $$SENSIBLE = sensato, com bom senso (a sensible decision). SENSITIVE = sensível, que se magoa/reage fácil (very sensitive skin). 'Sensível' em português é sensitive, não sensible!$$, $$Sensible shoes = sapatos práticos (não sapatos emotivos 😄).$$, $j$[{"en": "Wearing a helmet is the sensible thing to do.", "pt": "Usar capacete é o sensato a fazer."}, {"en": "She's very sensitive to criticism.", "pt": "Ela é muito sensível a críticas."}, {"en": "That was a sensible decision.", "pt": "Foi uma decisão sensata."}]$j$::jsonb, $j$[{"q": "'Sensato':", "ctx": "", "opts": ["sensible", "sensitive", "sensational", "sensed"], "ans": 0, "exp": "Bom senso."}, {"q": "'Sensível (se magoa fácil)':", "ctx": "", "opts": ["sensitive", "sensible", "sentimental only", "soft always"], "ans": 0, "exp": "Sensitive."}, {"q": "'Pele sensível':", "ctx": "", "opts": ["sensitive skin", "sensible skin", "sentient skin", "sensed skin"], "ans": 0, "exp": "Sensitive."}, {"q": "'Decisão sensata':", "ctx": "", "opts": ["sensible decision", "sensitive decision", "emotional decision", "sensational decision"], "ans": 0, "exp": "Sensible."}, {"q": "'Assunto delicado':", "ctx": "", "opts": ["sensitive topic", "sensible topic", "soft topic", "sensed topic"], "ans": 0, "exp": "Sensitive issue."}, {"q": "Falso amigo! 'Sensible' NÃO é:", "ctx": "", "opts": ["sensível", "sensato", "prático", "racional"], "ans": 0, "exp": "Parece, mas não é."}]$j$::jsonb),
('B2', 6047, $$Actually, Eventually, Ultimately$$, $$advérbios que enganam$$, $$🎪$$, $$Falsos amigos adverbiais: actually = na verdade (não 'atualmente'!); eventually = no fim, após um tempo (não 'eventualmente'!); currently = atualmente; occasionally = eventualmente/às vezes.$$, $$Actually ≠ atualmente! Currently = atualmente. O trio do vestibular.$$, $j$[{"en": "Actually, I've never been there.", "pt": "Na verdade, nunca estive lá."}, {"en": "We eventually found the hotel.", "pt": "No fim, encontramos o hotel."}, {"en": "She's currently working in Recife.", "pt": "Ela está trabalhando atualmente em Recife."}]$j$::jsonb, $j$[{"q": "'Actually' =", "ctx": "", "opts": ["na verdade", "atualmente", "com atualidade", "agora mesmo"], "ans": 0, "exp": "Falso amigo nº 1."}, {"q": "'Eventually' =", "ctx": "", "opts": ["no fim, finalmente", "eventualmente/às vezes", "com sorte", "raramente"], "ans": 0, "exp": "Depois de um processo."}, {"q": "'Atualmente':", "ctx": "", "opts": ["currently", "actually", "eventually", "presently never"], "ans": 0, "exp": "Currently/nowadays."}, {"q": "'Às vezes/eventualmente':", "ctx": "", "opts": ["occasionally", "eventually", "actually", "currently"], "ans": 0, "exp": "Occasionally."}, {"q": "'Na verdade, eu gostei':", "ctx": "", "opts": ["Actually, I liked it", "Currently, I liked it", "Eventually, I liked", "Occasionally, I liked"], "ans": 0, "exp": "Correção/surpresa."}, {"q": "'Ultimately' =", "ctx": "", "opts": ["em última análise", "ultimamente", "por último na fila", "urgentemente"], "ans": 0, "exp": "No fundo/no fim das contas."}]$j$::jsonb),
('B2', 6048, $$Sufixos de substantivo$$, $$-tion, -ment, -ness$$, $$🏗️$$, $$Fabricando substantivos: -tion (inform → information), -ment (develop → development), -ness (happy → happiness), -ity (able → ability), -ship (friend → friendship).$$, $$Adjetivo + -ness, verbo + -tion/-ment. Happiness, decision, movement.$$, $j$[{"en": "Thank you for the information.", "pt": "Obrigado pela informação."}, {"en": "Happiness can't be bought.", "pt": "A felicidade não se compra."}, {"en": "Our friendship means a lot to me.", "pt": "Nossa amizade significa muito para mim."}]$j$::jsonb, $j$[{"q": "Substantivo de 'develop':", "ctx": "", "opts": ["development", "developness", "developity", "develoption"], "ans": 0, "exp": "-ment."}, {"q": "Substantivo de 'happy':", "ctx": "", "opts": ["happiness", "happition", "happiment", "happity"], "ans": 0, "exp": "-ness."}, {"q": "Substantivo de 'decide':", "ctx": "", "opts": ["decision", "decidement", "decideness", "decidity"], "ans": 0, "exp": "-sion."}, {"q": "Substantivo de 'able':", "ctx": "", "opts": ["ability", "ableness", "ablement", "abletion"], "ans": 0, "exp": "-ity."}, {"q": "Substantivo de 'friend' (relação):", "ctx": "", "opts": ["friendship", "friendness", "friendity", "friendment"], "ans": 0, "exp": "-ship."}, {"q": "Substantivo de 'weak':", "ctx": "", "opts": ["weakness", "weakity", "weakment", "weaktion"], "ans": 0, "exp": "Fraqueza."}]$j$::jsonb),
('B2', 6049, $$Sufixos de adjetivo$$, $$-ful, -less, -able$$, $$🎨$$, $$Fabricando adjetivos: -ful (cheio de: hopeful), -less (sem: hopeless), -able (que pode: washable), -ous (famous), -y (rainy). Um par mágico: careful (cuidadoso) × careless (descuidado).$$, $$-ful e -less são opostos: useful × useless, harmful × harmless.$$, $j$[{"en": "Be careful with that glass!", "pt": "Cuidado com esse copo!"}, {"en": "This app is really useful.", "pt": "Este app é muito útil."}, {"en": "It's a hopeless situation.", "pt": "É uma situação sem esperança."}]$j$::jsonb, $j$[{"q": "'Sem esperança':", "ctx": "", "opts": ["hopeless", "hopeful", "unhoped", "hopity"], "ans": 0, "exp": "-less = sem."}, {"q": "'Útil':", "ctx": "", "opts": ["useful", "useless", "usable only", "usefull"], "ans": 0, "exp": "Um L só!"}, {"q": "'Que dá para lavar':", "ctx": "", "opts": ["washable", "washful", "washless", "washy"], "ans": 0, "exp": "-able = pode ser."}, {"q": "'Descuidado':", "ctx": "", "opts": ["careless", "careful", "uncare", "carefree same"], "ans": 0, "exp": "Sem cuidado."}, {"q": "'Inofensivo':", "ctx": "", "opts": ["harmless", "harmful", "harmable", "harmy"], "ans": 0, "exp": "Sem dano."}, {"q": "'Chuvoso':", "ctx": "", "opts": ["rainy", "rainful", "rainable", "rainous"], "ans": 0, "exp": "-y: sunny, windy, rainy."}]$j$::jsonb),
('B2', 6050, $$Vocabulário: saúde e médico$$, $$no consultório$$, $$🏥$$, $$Kit sobrevivência médica: appointment (consulta), prescription (receita), symptoms (sintomas), painkiller (analgésico), sore throat (dor de garganta), blood pressure (pressão), get better (melhorar).$$, $$Marcar consulta = make an appointment (não 'mark'!).$$, $j$[{"en": "I'd like to make an appointment.", "pt": "Gostaria de marcar uma consulta."}, {"en": "The doctor gave me a prescription.", "pt": "O médico me deu uma receita."}, {"en": "I have a sore throat and a fever.", "pt": "Estou com dor de garganta e febre."}]$j$::jsonb, $j$[{"q": "'Consulta médica':", "ctx": "", "opts": ["appointment", "date", "meeting", "reunion"], "ans": 0, "exp": "Doctor's appointment."}, {"q": "'Receita médica':", "ctx": "", "opts": ["prescription", "recipe", "receipt", "note"], "ans": 0, "exp": "Recipe é de bolo!"}, {"q": "'Analgésico':", "ctx": "", "opts": ["painkiller", "pain stopper", "hurt pill", "ache cutter"], "ans": 0, "exp": "Painkiller."}, {"q": "'Dor de garganta':", "ctx": "", "opts": ["sore throat", "throat pain hurt", "neck ache", "sick throat"], "ans": 0, "exp": "Sore throat."}, {"q": "'Pressão arterial':", "ctx": "", "opts": ["blood pressure", "blood tension", "vein pressure", "heart pressure"], "ans": 0, "exp": "Blood pressure."}, {"q": "'Melhorar (de doença)':", "ctx": "", "opts": ["get better", "turn good", "grow fine", "make well"], "ans": 0, "exp": "Get well soon!"}]$j$::jsonb),
('B2', 6051, $$Vocabulário: meio ambiente$$, $$planeta em pauta$$, $$🌱$$, $$O vocabulário das discussões do século: climate change (mudança climática), pollution (poluição), renewable energy (energia renovável), waste (desperdício/lixo), recycle (reciclar), endangered species (espécies ameaçadas).$$, $$Global warming = aquecimento global; greenhouse effect = efeito estufa.$$, $j$[{"en": "Climate change affects everyone.", "pt": "A mudança climática afeta todos."}, {"en": "We should use more renewable energy.", "pt": "Deveríamos usar mais energia renovável."}, {"en": "Don't waste water!", "pt": "Não desperdice água!"}]$j$::jsonb, $j$[{"q": "'Mudança climática':", "ctx": "", "opts": ["climate change", "weather change", "clima changing", "sky change"], "ans": 0, "exp": "Climate ≠ weather."}, {"q": "'Energia renovável':", "ctx": "", "opts": ["renewable energy", "renewed power", "recycled energy", "returnable energy"], "ans": 0, "exp": "Renewable."}, {"q": "'Desperdiçar':", "ctx": "", "opts": ["waste", "spend", "lose", "trash verb"], "ans": 0, "exp": "Don't waste!"}, {"q": "'Efeito estufa':", "ctx": "", "opts": ["greenhouse effect", "green effect", "hot house effect", "glass effect"], "ans": 0, "exp": "Greenhouse."}, {"q": "'Espécies ameaçadas':", "ctx": "", "opts": ["endangered species", "dangerous species", "risky animals", "extinct now species"], "ans": 0, "exp": "Endangered."}, {"q": "'Poluição do ar':", "ctx": "", "opts": ["air pollution", "air dirt", "sky pollution", "air contamination only"], "ans": 0, "exp": "Air pollution."}]$j$::jsonb),
('B2', 6052, $$Vocabulário: tecnologia e internet$$, $$vida online$$, $$💻$$, $$O inglês da era digital: download/upload (baixar/subir), password (senha), sign up (cadastrar-se), log in (entrar), update (atualizar), device (aparelho), wireless (sem fio).$$, $$Sign up = criar conta; log in = entrar com a conta que já existe.$$, $j$[{"en": "I forgot my password again!", "pt": "Esqueci minha senha de novo!"}, {"en": "Sign up for free on our website.", "pt": "Cadastre-se grátis no nosso site."}, {"en": "You need to update the app.", "pt": "Você precisa atualizar o aplicativo."}]$j$::jsonb, $j$[{"q": "'Senha':", "ctx": "", "opts": ["password", "passport", "keyword secret", "codeword"], "ans": 0, "exp": "Password."}, {"q": "'Cadastrar-se':", "ctx": "", "opts": ["sign up", "sign in", "log up", "enter in"], "ans": 0, "exp": "Sign up = criar conta."}, {"q": "'Entrar (conta existente)':", "ctx": "", "opts": ["log in", "log up", "sign new", "enter up"], "ans": 0, "exp": "Log in / sign in."}, {"q": "'Atualizar (software)':", "ctx": "", "opts": ["update", "upgrade only", "uplift", "renew always"], "ans": 0, "exp": "Update the app."}, {"q": "'Aparelho/dispositivo':", "ctx": "", "opts": ["device", "devise", "machine only", "gadget only"], "ans": 0, "exp": "Device."}, {"q": "'Baixar um arquivo':", "ctx": "", "opts": ["download", "upload", "underload", "offload"], "ans": 0, "exp": "Down = para baixo (para você)."}]$j$::jsonb),
('B2', 6053, $$Vocabulário: aeroporto e voo$$, $$modo avião$$, $$🛫$$, $$Sobreviva ao aeroporto: check-in, boarding pass (cartão de embarque), gate (portão), luggage/baggage (bagagem), delayed (atrasado), layover (escala), aisle/window seat (corredor/janela).$$, $$Escala = layover (AmE) ou stopover. "The flight was delayed" = clássico.$$, $j$[{"en": "Your boarding pass, please.", "pt": "Seu cartão de embarque, por favor."}, {"en": "The flight was delayed two hours.", "pt": "O voo atrasou duas horas."}, {"en": "Window or aisle seat?", "pt": "Janela ou corredor?"}]$j$::jsonb, $j$[{"q": "'Cartão de embarque':", "ctx": "", "opts": ["boarding pass", "flight card", "enter ticket", "plane pass card"], "ans": 0, "exp": "Boarding pass."}, {"q": "'Bagagem':", "ctx": "", "opts": ["luggage", "baggages", "luggages", "bags always"], "ans": 0, "exp": "Incontável!"}, {"q": "'Atrasado (voo)':", "ctx": "", "opts": ["delayed", "lated", "postponed only", "slowed"], "ans": 0, "exp": "Delayed."}, {"q": "'Escala':", "ctx": "", "opts": ["layover", "stopdown", "pause flight", "middle stop"], "ans": 0, "exp": "Layover/stopover."}, {"q": "'Assento no corredor':", "ctx": "", "opts": ["aisle seat", "corridor seat", "hall seat", "side seat"], "ans": 0, "exp": "Aisle (o s é mudo!)."}, {"q": "'Portão de embarque':", "ctx": "", "opts": ["gate", "door", "entrance", "port"], "ans": 0, "exp": "Gate 15."}]$j$::jsonb),
('B2', 6054, $$Vocabulário: banco e dinheiro$$, $$a vida financeira$$, $$🏦$$, $$Sem sufoco no banco: account (conta), savings (poupança), loan (empréstimo), mortgage (financiamento imobiliário), interest rate (taxa de juros), withdraw (sacar), deposit (depositar), afford (ter condições de pagar).$$, $$I can't afford it = não tenho condições (não é 'não posso pagar hoje', é 'não cabe no bolso').$$, $j$[{"en": "I'd like to open an account.", "pt": "Gostaria de abrir uma conta."}, {"en": "The interest rates are very high.", "pt": "As taxas de juros estão altíssimas."}, {"en": "We can't afford a new car right now.", "pt": "Não temos condições de comprar um carro agora."}]$j$::jsonb, $j$[{"q": "'Sacar dinheiro':", "ctx": "", "opts": ["withdraw", "deposit", "take off money", "pull money"], "ans": 0, "exp": "Withdraw cash."}, {"q": "'Poupança':", "ctx": "", "opts": ["savings", "safes", "keeps", "storage money"], "ans": 0, "exp": "Savings account."}, {"q": "'Empréstimo':", "ctx": "", "opts": ["loan", "lend noun", "borrow noun", "rent"], "ans": 0, "exp": "A bank loan."}, {"q": "'Financiamento da casa':", "ctx": "", "opts": ["mortgage", "house loaning", "home renting", "long buy"], "ans": 0, "exp": "Mortgage (t mudo)."}, {"q": "'Taxa de juros':", "ctx": "", "opts": ["interest rate", "tax rate", "interesting fee", "money rate"], "ans": 0, "exp": "Interest."}, {"q": "'Ter condições de pagar':", "ctx": "", "opts": ["afford", "pay able", "support", "conditions to"], "ans": 0, "exp": "I can't afford it."}]$j$::jsonb),
('B2', 6055, $$Vocabulário: universidade$$, $$vida acadêmica$$, $$🎓$$, $$Inglês do campus: degree (diploma/graduação), major (curso principal, AmE), scholarship (bolsa), undergraduate (graduando), assignment (trabalho), lecture (aula expositiva), take/pass/fail an exam.$$, $$Fazer prova = TAKE an exam (não make!). Passar = pass; reprovar = fail.$$, $j$[{"en": "She has a degree in Engineering.", "pt": "Ela é formada em Engenharia."}, {"en": "He got a full scholarship.", "pt": "Ele conseguiu bolsa integral."}, {"en": "I have to take an exam tomorrow.", "pt": "Tenho que fazer uma prova amanhã."}]$j$::jsonb, $j$[{"q": "'Diploma/graduação':", "ctx": "", "opts": ["degree", "diploma paper only", "graduation hat", "grade"], "ans": 0, "exp": "A degree in law."}, {"q": "'Bolsa de estudos':", "ctx": "", "opts": ["scholarship", "study bag", "school ship", "grant only informal"], "ans": 0, "exp": "Scholarship."}, {"q": "'Fazer uma prova':", "ctx": "", "opts": ["take an exam", "make an exam", "do exam a", "write exam only"], "ans": 0, "exp": "Take!"}, {"q": "'Reprovar na prova':", "ctx": "", "opts": ["fail the exam", "lose the exam", "miss the exam", "drop the exam"], "ans": 0, "exp": "Fail."}, {"q": "'Trabalho/tarefa da faculdade':", "ctx": "", "opts": ["assignment", "signature", "homework house", "duty paper"], "ans": 0, "exp": "Assignment."}, {"q": "'Curso principal' (AmE):", "ctx": "", "opts": ["major", "mayor", "master", "main class"], "ans": 0, "exp": "Major in Biology."}]$j$::jsonb),
('B2', 6056, $$Vocabulário: mídia e notícias$$, $$lendo o mundo$$, $$📰$$, $$Para entender o noticiário: headline (manchete), breaking news (últimas notícias), source (fonte), coverage (cobertura), bias (viés), fake news, press (imprensa), broadcast (transmitir).$$, $$Reliable source = fonte confiável. A pergunta de ouro da era digital.$$, $j$[{"en": "Did you see today's headlines?", "pt": "Viu as manchetes de hoje?"}, {"en": "The story comes from a reliable source.", "pt": "A matéria vem de uma fonte confiável."}, {"en": "The game was broadcast live.", "pt": "O jogo foi transmitido ao vivo."}]$j$::jsonb, $j$[{"q": "'Manchete':", "ctx": "", "opts": ["headline", "head title", "top news word", "big letter"], "ans": 0, "exp": "Headline."}, {"q": "'Últimas notícias (urgente)':", "ctx": "", "opts": ["breaking news", "broken news", "fast news", "hot news only"], "ans": 0, "exp": "Breaking!"}, {"q": "'Fonte (da informação)':", "ctx": "", "opts": ["source", "sauce", "start", "resource only"], "ans": 0, "exp": "Reliable source."}, {"q": "'Viés/parcialidade':", "ctx": "", "opts": ["bias", "bies", "side lean", "opinion only"], "ans": 0, "exp": "Media bias."}, {"q": "'Imprensa':", "ctx": "", "opts": ["the press", "the print", "the pressing", "the papers only"], "ans": 0, "exp": "Freedom of the press."}, {"q": "'Transmitir (TV/rádio)':", "ctx": "", "opts": ["broadcast", "broadcatch", "throw signal", "netcast only"], "ans": 0, "exp": "Broadcast live."}]$j$::jsonb),
('B2', 6057, $$Dar conselhos$$, $$If I were you...$$, $$🦉$$, $$Aconselhar com elegância: If I were you, I'd... (se eu fosse você), You'd better (é melhor você — aviso forte), You should (deveria), Why don't you...? (por que você não...?), It might be a good idea to...$$, $$You'd better + verbo sem to: You'd better GO (não to go!). E carrega tom de aviso.$$, $j$[{"en": "If I were you, I'd accept the offer.", "pt": "Se eu fosse você, aceitaria a oferta."}, {"en": "You'd better see a doctor.", "pt": "É melhor você ir ao médico."}, {"en": "Why don't you talk to her?", "pt": "Por que você não fala com ela?"}]$j$::jsonb, $j$[{"q": "'Se eu fosse você...':", "ctx": "", "opts": ["If I were you", "If I was be you", "If I am you", "When I were you"], "ans": 0, "exp": "Were para todos!"}, {"q": "'É melhor você ir':", "ctx": "", "opts": ["You'd better go", "You'd better to go", "You better going", "You would better go to"], "ans": 0, "exp": "Sem to!"}, {"q": "'You'd better' carrega tom de:", "ctx": "", "opts": ["aviso (ou algo ruim acontece)", "pedido gentil", "dúvida", "elogio"], "ans": 0, "exp": "Advertência."}, {"q": "Sugestão leve:", "ctx": "", "opts": ["Why don't you try?", "You must try!", "Try or else!", "You'd better try!"], "ans": 0, "exp": "Why don't you...?"}, {"q": "'Talvez seja boa ideia...':", "ctx": "", "opts": ["It might be a good idea to...", "It must be idea good...", "Better idea is that...", "Good idea you do..."], "ans": 0, "exp": "Suave e educado."}, {"q": "Conselho + forte → mais fraco:", "ctx": "", "opts": ["must > should > might want to", "might > should > must", "should > must > might", "todos iguais"], "ans": 0, "exp": "Escala de força."}]$j$::jsonb),
('B2', 6058, $$Reclamando com classe$$, $$polite complaints$$, $$😤$$, $$Reclamar sem barraco: I'm afraid there's a problem with... (receio que haja um problema), This isn't what I ordered (não foi o que pedi), Could you sort this out? (pode resolver?), I'd like a refund (quero reembolso).$$, $$"I'm afraid..." abre reclamação educada — você não está com medo, está sendo britânico.$$, $j$[{"en": "I'm afraid there's a problem with my order.", "pt": "Receio que haja um problema com meu pedido."}, {"en": "Excuse me, this isn't what I ordered.", "pt": "Com licença, não foi isso que pedi."}, {"en": "I'd like a refund, please.", "pt": "Gostaria de um reembolso, por favor."}]$j$::jsonb, $j$[{"q": "Abertura educada de reclamação:", "ctx": "", "opts": ["I'm afraid there's a problem", "You made a mistake!", "This is wrong, fix it", "Listen here right now"], "ans": 0, "exp": "Suave e firme."}, {"q": "'Reembolso':", "ctx": "", "opts": ["refund", "refound", "payback informal", "money return paper"], "ans": 0, "exp": "A refund."}, {"q": "'Pode resolver isso?':", "ctx": "", "opts": ["Could you sort this out?", "Can you solve me?", "Fix this you can?", "You will resolve?"], "ans": 0, "exp": "Sort out."}, {"q": "'Não foi o que pedi':", "ctx": "", "opts": ["This isn't what I ordered", "This no my order", "I no ordered this", "Wrong thing you gave"], "ans": 0, "exp": "Educado e claro."}, {"q": "'Trocar (produto)':", "ctx": "", "opts": ["exchange", "change money", "trade in only", "swap always"], "ans": 0, "exp": "Exchange it."}, {"q": "Escalando com educação:", "ctx": "", "opts": ["I'd like to speak to the manager", "Call your boss now!", "You're all useless", "I'll scream"], "ans": 0, "exp": "Falar com o gerente."}]$j$::jsonb),
('B2', 6059, $$Ao telefone$$, $$hold on, put through$$, $$📞$$, $$Inglês telefônico: Who's calling? (quem fala?), Hold on/hang on (aguarde), put you through (transferir), leave a message (deixar recado), call back (retornar), hang up (desligar), You're breaking up (está cortando).$$, $$Hang on = espere; hang up = desligue. Uma preposição salva (ou mata) a ligação!$$, $j$[{"en": "Hold on, I'll put you through.", "pt": "Aguarde, vou transferir você."}, {"en": "Can I leave a message?", "pt": "Posso deixar um recado?"}, {"en": "Sorry, you're breaking up.", "pt": "Desculpe, sua voz está cortando."}]$j$::jsonb, $j$[{"q": "'Aguarde na linha':", "ctx": "", "opts": ["Hold on", "Hang up", "Call off", "Put down"], "ans": 0, "exp": "Hold/hang on."}, {"q": "'Vou transferir você':", "ctx": "", "opts": ["I'll put you through", "I'll put you over", "I'll pass you along phone", "I'll send you up"], "ans": 0, "exp": "Put through."}, {"q": "'Desligar':", "ctx": "", "opts": ["hang up", "hang on", "hold up", "shut on"], "ans": 0, "exp": "Hang up."}, {"q": "'Retornar a ligação':", "ctx": "", "opts": ["call back", "call again word", "return call verb", "recall you"], "ans": 0, "exp": "Call you back."}, {"q": "'Está cortando (sinal)':", "ctx": "", "opts": ["You're breaking up", "You're cutting off me", "You're falling down", "You're hanging on"], "ans": 0, "exp": "Breaking up."}, {"q": "'Quem fala?':", "ctx": "", "opts": ["Who's calling?", "Who talks?", "Who is it there speak?", "Whom calling?"], "ans": 0, "exp": "Who's calling, please?"}]$j$::jsonb),
('B2', 6060, $$Inglês de reuniões$$, $$let's get started$$, $$🤝$$, $$Sobreviva à meeting: Let's get started (vamos começar), Can everyone see my screen? (todos veem minha tela?), moving on (seguindo), to sum up (resumindo), any questions? (dúvidas?), follow up (dar seguimento).$$, $$Action items = tarefas definidas na reunião. Anote as suas!$$, $j$[{"en": "Let's get started, shall we?", "pt": "Vamos começar?"}, {"en": "Moving on to the next topic...", "pt": "Passando ao próximo tópico..."}, {"en": "I'll follow up by email.", "pt": "Vou dar seguimento por e-mail."}]$j$::jsonb, $j$[{"q": "'Vamos começar':", "ctx": "", "opts": ["Let's get started", "Let's get begin", "Start we now", "Begin us"], "ans": 0, "exp": "Get started."}, {"q": "'Resumindo':", "ctx": "", "opts": ["to sum up", "to sum on", "for short talk", "summing top"], "ans": 0, "exp": "To sum up..."}, {"q": "'Passando ao próximo ponto':", "ctx": "", "opts": ["moving on", "moving up", "passing over all", "next going"], "ans": 0, "exp": "Moving on."}, {"q": "'Dar seguimento':", "ctx": "", "opts": ["follow up", "follow on top", "go after it", "continue up"], "ans": 0, "exp": "Follow up."}, {"q": "'Alguma dúvida?':", "ctx": "", "opts": ["Any questions?", "Some doubts?", "Any doubts word?", "Questions anyone has them?"], "ans": 0, "exp": "Any questions?"}, {"q": "'Adiar a reunião':", "ctx": "", "opts": ["postpone the meeting", "pospone the meeting", "late the meeting", "delay on meeting verb"], "ans": 0, "exp": "Postpone."}]$j$::jsonb),
('B2', 6061, $$Concordar e discordar$$, $$I see your point, but...$$, $$⚖️$$, $$Debata sem brigar: I couldn't agree more (concordo total), You have a point (você tem razão nisso), I see what you mean, but... (entendo, mas), I'm not so sure about that (não sei não), Fair enough (justo).$$, $$Discordância educada = concorde um pouco primeiro, depois vire: "True, but..."$$, $j$[{"en": "You have a point, but there's another issue.", "pt": "Você tem razão, mas há outra questão."}, {"en": "I'm not so sure about that.", "pt": "Não tenho tanta certeza disso."}, {"en": "Fair enough, let's try your idea.", "pt": "Justo, vamos tentar sua ideia."}]$j$::jsonb, $j$[{"q": "Concordância total:", "ctx": "", "opts": ["I couldn't agree more", "I couldn't agree", "I don't agree more", "I agree never more"], "ans": 0, "exp": "Não poderia concordar mais."}, {"q": "'Você tem razão (nesse ponto)':", "ctx": "", "opts": ["You have a point", "You have a reason", "You are point", "Your point right"], "ans": 0, "exp": "Have a point."}, {"q": "Discordância suave:", "ctx": "", "opts": ["I'm not so sure about that", "You're wrong", "That's nonsense", "No way ever"], "ans": 0, "exp": "Educado."}, {"q": "'Fair enough' =", "ctx": "", "opts": ["justo, faz sentido", "bastante justo de preço", "loiro o suficiente", "tanto faz"], "ans": 0, "exp": "Aceito seu argumento."}, {"q": "'Entendo o que quer dizer, mas...':", "ctx": "", "opts": ["I see what you mean, but", "I look your meaning, but", "I watch you mean, but", "I see you say, but"], "ans": 0, "exp": "I see what you mean."}, {"q": "'Let's agree to disagree' =", "ctx": "", "opts": ["fiquemos cada um com sua opinião", "vamos concordar", "vamos brigar", "desistimos"], "ans": 0, "exp": "Empate amigável."}]$j$::jsonb);